INSERT INTO public.products (archetype_id, name, description, valid_industries, brain, sort_order)
VALUES
  ('booking_core', 'Booking & Appointments', 'Service booking platform connecting users with providers. Industry brain defines what is being booked. This core defines how booking works.', '{}', '{"archetype_id":"booking_core","archetype_name":"Booking & Appointments","description":"Service booking platform connecting users with providers. Industry brain defines what is being booked. This core defines how booking works.","valid_industries":["Beauty & Wellness","Retail & Fashion","Food & Beverage","Healthcare","Finance","Education","Fitness & Sport","Travel & Lifestyle","Real Estate","Transport & Logistics","Events & Ticketing","Entertainment & Media","AI & Technology","Developer Tools"],"icon_pack":{"default_library":{"name":"Lucide","variant":"Rounded line","url":"https://lucide.dev"},"industry_overrides":{"Beauty & Wellness":{"name":"Phosphor Icons","variant":"Duotone","url":"https://phosphoricons.com"},"Healthcare":{"name":"Material Symbols","variant":"Rounded","url":"https://fonts.google.com/icons"},"Fitness & Sport":{"name":"Tabler Icons","variant":"Bold line","url":"https://tabler.io/icons"},"Real Estate":{"name":"Material Symbols","variant":"Outlined","url":"https://fonts.google.com/icons"}},"core_nav_icons":["home","search","calendar","heart","user","bell","clock","list","arrow-back","check"],"core_domain_icons":["calendar","clock","check-circle","star","user","map-pin","repeat","bell","plus","x"]},"landing_page":{"sections":[{"id":"hero","generates_images":true},{"id":"how_it_works","generates_images":false},{"id":"cta_footer","generates_images":false}],"three_js":{"style":"soft_orbs","description":"Soft glowing orbs of varying sizes drifting slowly. Calm, approachable. Orbs pulse gently. No hard geometry.","intensity":"very_subtle","interaction":"mouse_parallax","avoid":"no status pills, no hero-stat-line, no ticker strips"}},"core_entities":{"entities":["User","Provider","Service","Availability","Appointment","Review","Payment","Notification","Location","WaitList","Package","Staff"],"relationships":["Provider offers many Services","Provider has Staff members","Service has Availability slots","User books an Appointment for a Service with a Provider","Appointment has a Payment","Appointment has a Status (pending, confirmed, completed, cancelled, no-show)","User writes a Review about a Provider or Service after Appointment","Provider has a Location","User can join a WaitList for a fully booked Service or time slot","Package belongs to Provider, bundles multiple Services","Notification belongs to User, triggered by Appointment status changes"]},"tiers":{"mvp":{"tier":"MVP","description":"Core booking — discover provider, view services, book appointment, manage bookings.","screen_count":9,"primary_flows":["Browse providers → view provider detail → select service → pick date and time → confirm booking → receive confirmation","View upcoming appointments → manage or cancel","Receive reminder notification → view appointment detail"],"secondary_flows":["Search for provider by name or location","Leave review after completed appointment","Add appointment to calendar","Contact provider directly"],"screens":[{"id":"home_discover","name":"Home / Discover","purpose":"Browse and discover providers — featured, nearby, category filter","visual":"Industry brain visual. Provider cards with rating and distance. Category chips. Search bar.","entities":["Provider","Service","Location"],"actions":["Search providers","Browse categories","Filter by location or rating","Tap provider card","View featured providers"],"copy":{"headline":"{{industry.copy_by_app_type[''Booking & Appointments''].headline}}","cta":"{{industry.copy_by_app_type[''Booking & Appointments''].cta}}","empty_state":"No providers in your area yet — check back soon."}},{"id":"provider_detail","name":"Provider Detail","purpose":"Full provider profile — services, availability preview, reviews","visual":"Provider images. Rating and review count. Services list. Book CTA.","entities":["Provider","Service","Review","Staff","Location"],"actions":["View provider photos","View all services","View reviews","View location on map","Select a service to book","Contact provider","Save to favourites"]},{"id":"service_detail","name":"Service Detail","purpose":"Service information — duration, price, description, staff selector","visual":"Service image. Duration and price prominent. Staff selector. Book CTA.","entities":["Service","Provider","Staff","Availability"],"actions":["View service details","Select staff member (if applicable)","View price breakdown","Proceed to date and time selection"]},{"id":"date_time_picker","name":"Date & Time Selection","purpose":"Pick available date and time slot","visual":"Calendar view. Available slots grid below. Selected state highlighted.","entities":["Availability","Appointment"],"actions":["Browse available dates","Select time slot","View unavailable slots (greyed)","Join waitlist for fully booked slot","Proceed to booking confirmation"]},{"id":"booking_confirmation","name":"Booking Confirmation","purpose":"Review and confirm booking details before payment","visual":"Summary card — provider, service, date, time, price. Payment method. Confirm CTA.","entities":["Appointment","Service","Provider","Payment"],"actions":["Review booking summary","Select or add payment method","Apply voucher or promo code","Confirm and pay","View cancellation policy"]},{"id":"booking_success","name":"Booking Success","purpose":"Confirmation screen post-booking","visual":"Success animation. Booking summary. Add to calendar CTA. View appointments CTA.","entities":["Appointment"],"actions":["Add to calendar","Share booking","View all appointments","Return to home"]},{"id":"appointments","name":"My Appointments","purpose":"Upcoming and past appointments","visual":"Upcoming tab and past tab. Appointment cards with status badges.","entities":["Appointment","Provider","Service"],"actions":["View upcoming appointments","View past appointments","Tap appointment for detail","Cancel appointment","Reschedule","Leave review on past appointment"],"copy":{"headline":"Your appointments","cta":"Book again","empty_state":"No upcoming appointments. Book your first one now."}},{"id":"appointment_detail","name":"Appointment Detail","purpose":"Full appointment detail — status, directions, contact","visual":"Status stepper. Provider info. Service summary. Map. Actions.","entities":["Appointment","Provider","Service","Location"],"actions":["View appointment status","Get directions","Contact provider","Cancel appointment","Reschedule","Add to calendar"]},{"id":"profile_settings","name":"Profile & Settings","purpose":"User profile and app settings","visual":"Avatar. Profile details. Settings list. Notification preferences.","entities":["User"],"actions":["Edit profile","Manage payment methods","Notification preferences","View saved providers","Log out"]}],"interaction_patterns":["Calendar picker highlights available dates in accent colour — unavailable greyed out","Time slot grid — available slots as tappable chips, booked slots greyed","Booking confirmation has a 5-second cancel window after submit","Appointment status badge — pending yellow, confirmed green, cancelled red","Add to calendar triggers native calendar integration","Review prompt appears 1 hour after appointment end time","Provider cards show next available slot time — not just availability"]},"startup":{"tier":"Startup","description":"Full booking platform with packages, waitlist, notifications, reviews, and provider management.","screen_count":14,"primary_flows":["All MVP flows","Browse packages → select package → book series of appointments","Join waitlist → receive notification when slot opens → confirm booking","Provider manages calendar → blocks time → sets availability","Receive review → respond to review"],"secondary_flows":["All MVP secondary flows","Recurring appointment setup","Group booking","Gift voucher purchase and redemption","Loyalty points earn and redeem","Provider sets service promotions"],"screens":[{"id":"home_discover","name":"Home / Discover","purpose":"Personalised discovery with recommended providers and promotions","visual":"Personalised feed. Saved providers row. Promotions. Categories.","entities":["Provider","Service","Location","Promotion"],"actions":["Search","Browse categories","View saved providers","Tap promotions","View recommended"],"copy":{"headline":"{{industry.copy_by_app_type[''Booking & Appointments''].headline}}","cta":"{{industry.copy_by_app_type[''Booking & Appointments''].cta}}","empty_state":"No providers in your area yet — check back soon."}},{"id":"search_map","name":"Search & Map View","purpose":"Find providers by location with map and list toggle","visual":"Map with provider pins. List below. Filter bar. Distance radius control.","entities":["Provider","Location"],"actions":["Search","Toggle map or list","Filter","Tap map pin","Set radius","Sort by distance or rating"]},{"id":"provider_detail","name":"Provider Detail","purpose":"Full provider profile with packages, staff, and reviews","visual":"Provider gallery. Stats. Services tab. Packages tab. Staff tab. Reviews tab.","entities":["Provider","Service","Package","Staff","Review"],"actions":["View services","View packages","Select staff","Read reviews","Save favourite","Book service or package"]},{"id":"service_detail","name":"Service Detail","purpose":"Full service detail with staff selection and add-ons","visual":"Service image. Duration, price, add-ons. Staff selector. Book CTA.","entities":["Service","Provider","Staff"],"actions":["View detail","Select staff","Add optional add-ons","Proceed to booking"]},{"id":"packages","name":"Packages","purpose":"Browse and purchase service packages or bundles","visual":"Package cards with savings badge. Service list per package. Buy CTA.","entities":["Package","Service","Provider"],"actions":["Browse packages","View package contents","View savings","Purchase package","Redeem package credit"]},{"id":"date_time_picker","name":"Date & Time Selection","purpose":"Book with waitlist and recurring options","visual":"Calendar. Time slots. Waitlist CTA on fully booked. Recurring toggle.","entities":["Availability","Appointment","WaitList"],"actions":["Select date and time","Join waitlist","Set recurring appointment","Proceed to confirm"]},{"id":"booking_confirmation","name":"Booking Confirmation","purpose":"Review and confirm with loyalty and voucher support","visual":"Summary. Payment. Loyalty points applied. Voucher field. Policy. Confirm.","entities":["Appointment","Service","Provider","Payment"],"actions":["Review summary","Apply loyalty points","Apply voucher","Select payment","Confirm"]},{"id":"booking_success","name":"Booking Success","purpose":"Confirmation with loyalty points earned","visual":"Success animation. Points earned badge. Calendar CTA. View appointments CTA.","entities":["Appointment"],"actions":["Add to calendar","Share","View appointments","Home"]},{"id":"appointments","name":"My Appointments","purpose":"Full appointment management with reschedule and recurring view","visual":"Upcoming and past tabs. Recurring badge on recurring appointments.","entities":["Appointment","Provider","Service"],"actions":["View upcoming","View past","Cancel","Reschedule","Manage recurring","Leave review"],"copy":{"headline":"Your appointments","cta":"Book again","empty_state":"No upcoming appointments. Book your first one now."}},{"id":"appointment_detail","name":"Appointment Detail","purpose":"Full detail with check-in and pre-appointment info","visual":"Status stepper. Provider info. Pre-appointment instructions. Map. Actions.","entities":["Appointment","Provider","Service","Location"],"actions":["View status","Directions","Contact","Cancel","Reschedule","Pre-appointment check-in"]},{"id":"notifications","name":"Notifications","purpose":"All appointment reminders, confirmations, and promotions","visual":"Categorised list. Reminder indicators. Deep link on tap.","entities":["Notification","Appointment"],"actions":["View all","Tap to navigate","Mark read","Manage notification preferences"]},{"id":"provider_dashboard","name":"Provider Dashboard","purpose":"Provider home — today''s schedule, upcoming, earnings snapshot","visual":"Today''s appointments timeline. Earnings card. Quick actions.","entities":["Provider","Appointment","Service"],"actions":["View today''s schedule","View earnings","Manage availability","View upcoming","Create service"]},{"id":"provider_calendar","name":"Provider Calendar / Availability","purpose":"Provider sets working hours, blocks time, manages availability","visual":"Week calendar view. Blocked time in grey. Booked slots. Availability toggle per day.","entities":["Provider","Availability","Appointment","Staff"],"actions":["Set working hours","Block time","View booked appointments","Manage staff availability"]},{"id":"profile_settings","name":"Profile & Settings","purpose":"Full profile with loyalty balance and notification settings","visual":"Profile. Loyalty points balance. Payment methods. Notifications. Settings.","entities":["User"],"actions":["Edit profile","View loyalty points","Payment methods","Notifications","Saved providers","Log out"]}],"interaction_patterns":["All MVP interaction patterns","Waitlist confirmation — user gets push notification when slot opens","Package credit balance visible on booking confirmation screen","Recurring appointment shows series summary before confirm","Provider calendar week view — swipe to navigate weeks","Loyalty points earned animation on booking success screen","Review prompt 1 hour post-appointment with one-tap star rating"]},"scale":{"tier":"Scale","description":"Multi-location booking platform with staff management, advanced analytics, membership, and white-label support.","screen_count":22,"primary_flows":["All MVP and Startup flows","Multi-location provider — user selects location → books at that branch","Membership signup → unlocks unlimited or discounted bookings → auto-renews","Provider views advanced analytics → adjusts pricing and availability → optimises revenue","Admin manages all providers → approves listings → resolves disputes → views platform KPIs","Gift card purchase → send to recipient → recipient redeems at checkout"],"secondary_flows":["All previous secondary flows","Dynamic pricing — peak time pricing set by provider","Multi-staff booking — book multiple staff for one appointment","Corporate accounts — company books for employees","Provider payouts and financial reporting","Custom booking form fields set by provider"],"screens":[{"id":"home_discover","name":"Home / Discover","purpose":"AI-personalised discovery with membership perks and nearby","visual":"Personalised. Membership banner. Nearby map preview. Categories.","entities":["Provider","Service","Location","Promotion"],"actions":["All Startup actions","View membership perks","Nearby map"],"copy":{"headline":"{{industry.copy_by_app_type[''Booking & Appointments''].headline}}","cta":"{{industry.copy_by_app_type[''Booking & Appointments''].cta}}","empty_state":"No providers in your area yet — check back soon."}},{"id":"search_map","name":"Search & Map","purpose":"Full map with multi-location provider support","visual":"Map. Multi-location pins. Cluster view for dense areas. Filters.","entities":["Provider","Location"],"actions":["All Startup actions","View multi-location providers","Cluster map navigation"]},{"id":"provider_detail","name":"Provider Detail","purpose":"Multi-location provider with location selector","visual":"Location selector at top. Gallery. Services. Staff. Reviews. Membership deals.","entities":["Provider","Service","Package","Staff","Review","Location"],"actions":["All Startup actions","Select location","View membership deals"]},{"id":"service_detail","name":"Service Detail","purpose":"Service with dynamic pricing and custom fields","visual":"Service detail. Dynamic pricing indicator. Custom booking fields. Book CTA.","entities":["Service","Provider","Staff"],"actions":["All Startup actions","View dynamic pricing","Fill custom booking fields"]},{"id":"packages","name":"Packages & Memberships","purpose":"Packages and recurring membership tiers","visual":"Packages tab. Membership tab. Savings badges. Subscribe CTA.","entities":["Package","Service","Provider"],"actions":["All Startup actions","Subscribe to membership","View membership tiers"]},{"id":"membership","name":"Membership","purpose":"Subscribe, manage, and view membership benefits","visual":"Active membership card. Perks list. Usage progress. Auto-renew toggle.","entities":["User"],"actions":["View membership","View perks","View usage","Toggle auto-renew","Upgrade tier","Cancel"]},{"id":"date_time_picker","name":"Date & Time Selection","purpose":"Booking with dynamic pricing, multi-staff, and peak indicators","visual":"Calendar. Peak time badges on slots. Multi-staff selector. Recurring.","entities":["Availability","Appointment","WaitList","Staff"],"actions":["All Startup actions","View peak pricing","Select multi-staff","View availability by staff"]},{"id":"booking_confirmation","name":"Booking Confirmation","purpose":"Full confirmation with membership, gift card, dynamic price summary","visual":"Full summary. Membership discount applied. Gift card field. Dynamic price breakdown.","entities":["Appointment","Service","Provider","Payment"],"actions":["All Startup actions","Apply gift card","View dynamic price breakdown"]},{"id":"booking_success","name":"Booking Success","purpose":"Confirmation with membership benefit earned","visual":"Success. Points earned. Membership benefit used. Calendar CTA.","entities":["Appointment"],"actions":["All Startup actions","View membership benefit used"]},{"id":"appointments","name":"My Appointments","purpose":"Full appointment list with corporate booking view","visual":"Personal and corporate tabs. Status. Recurring. Team bookings.","entities":["Appointment","Provider","Service"],"actions":["All Startup actions","View corporate bookings","View team appointments"],"copy":{"headline":"Your appointments","cta":"Book again","empty_state":"No upcoming appointments. Book your first one now."}},{"id":"appointment_detail","name":"Appointment Detail","purpose":"Full detail with invoice and corporate reference","visual":"Status stepper. Invoice download. Corporate reference field. Actions.","entities":["Appointment","Provider","Service","Location"],"actions":["All Startup actions","Download invoice","Add corporate reference"]},{"id":"gift_cards","name":"Gift Cards","purpose":"Purchase, send, and redeem gift cards","visual":"Gift card design selector. Amount input. Recipient details. Send CTA.","entities":["User"],"actions":["Purchase gift card","Select amount","Send to recipient","Redeem gift card","View gift card balance"]},{"id":"notifications","name":"Notifications","purpose":"Smart notifications with membership and peak pricing alerts","visual":"Priority alerts. Membership renewal. Peak pricing warnings. All activity.","entities":["Notification","Appointment"],"actions":["All Startup actions","View membership renewal alert","Peak pricing notification"]},{"id":"provider_dashboard","name":"Provider Dashboard","purpose":"Multi-location provider home with revenue and staff overview","visual":"Location selector. Revenue by location. Staff utilisation. Today''s schedule.","entities":["Provider","Appointment","Service","Staff"],"actions":["All Startup actions","Select location","View staff utilisation","View revenue by location"]},{"id":"provider_calendar","name":"Provider Calendar","purpose":"Full multi-staff calendar with dynamic pricing controls","visual":"Staff columns on calendar. Dynamic pricing overlay. Block and unblock.","entities":["Provider","Availability","Appointment","Staff"],"actions":["All Startup actions","Set dynamic pricing by time slot","View all staff calendars"]},{"id":"provider_analytics","name":"Provider Analytics","purpose":"Revenue, utilisation, customer retention, peak time analysis","visual":"Revenue trend. Utilisation heat map. Retention cohort. Peak times chart.","entities":["Provider","Appointment","Service","Staff"],"actions":["View revenue trend","View utilisation","View retention","View peak times","Export report"]},{"id":"staff_management","name":"Staff Management","purpose":"Manage staff profiles, services, and schedules","visual":"Staff list. Profile per staff. Services assigned. Schedule per staff.","entities":["Staff","Provider"],"actions":["Add staff","Edit staff profile","Assign services","View staff schedule","Set staff hours"]},{"id":"payouts","name":"Payouts & Financials","purpose":"Provider earnings, payout schedule, and financial reports","visual":"Earnings summary. Payout schedule. Commission breakdown. Download report.","entities":["Provider"],"actions":["View earnings","Request payout","View commission","Download financial report","View payout history"]},{"id":"admin_dashboard","name":"Admin Dashboard","purpose":"Platform KPIs, provider approvals, dispute queue","visual":"KPI cards. Provider approval queue. Dispute queue. Revenue chart.","entities":["User","Provider","Appointment"],"actions":["View KPIs","Approve providers","Resolve disputes","View platform revenue","Manage categories"]},{"id":"corporate_accounts","name":"Corporate Accounts","purpose":"Company books for employees — budget, team management, invoicing","visual":"Company profile. Team member list. Budget tracker. Invoice list.","entities":["User","Provider","Appointment"],"actions":["Manage team","Set booking budget","View team appointments","Download invoices","Add team member"]},{"id":"profile_settings","name":"Profile & Settings","purpose":"Full profile with membership, corporate, and privacy settings","visual":"Comprehensive settings. Membership section. Corporate section.","entities":["User"],"actions":["All Startup actions","Membership settings","Corporate account settings","Privacy controls"]},{"id":"help_centre","name":"Help Centre","purpose":"Self-serve help and support contact","visual":"Search. Article categories. Featured articles. Contact CTA.","entities":["User"],"actions":["Search articles","Browse","Read article","Contact support","Raise dispute"]}],"interaction_patterns":["All MVP and Startup interaction patterns","Dynamic pricing badge on peak slots — price shown in amber or red","Membership discount automatically applied at confirmation — highlighted in green","Multi-location map clusters — tap to expand and select location","Staff utilisation heat map — darker = busier — visual at a glance","Corporate booking shows company budget remaining — progress bar","Gift card design previews as user selects — live render","Provider payout pending vs available clearly colour coded"]}},"layout":{"iphone":{"nav":"bottom_tab_4","nav_items":["Discover","Bookings","Messages","Profile"],"content":"full_width_single_column","card_style":"full_width_provider_card","cta":"sticky_full_width_bottom","hero":"search_and_category_chips_top","padding":"16px horizontal","image_ratio":"16:9 provider hero 1:1 avatar"},"ipad":{"nav":"sidebar_left_with_labels","nav_items":["Discover","Bookings","Messages","Profile"],"content":"2col_split_list_left_detail_right","card_style":"compact_list_row","cta":"prominent_in_detail_panel_right","hero":"search_bar_with_date_range_picker","padding":"24px horizontal","image_ratio":"16:9 provider hero"},"desktop":{"nav":"top_navbar","nav_items":["Home","Find providers","My bookings","Messages","Profile"],"content":"3col_grid_max_1100px_centred","card_style":"horizontal_card_image_left_details_right","cta":"right_aligned_book_now_button","hero":"full_width_search_with_filters_below","padding":"48px horizontal","image_ratio":"3:2 provider card 16:9 hero"},"notes":"Calendar and time slot picker are the most critical UI elements — they must be flawless on all form factors. Never paginate time slots — always show as scrollable chip grid."},"constraints":{"avoid":["Never use a date picker modal — always use an inline calendar on the booking screen","Never show fully booked providers in primary results without a ''next available'' label","Never collect payment details before booking is confirmed","Never use ambiguous time formats — always show AM/PM or 24h consistently throughout","Never show a provider''s personal phone number or email on their public profile","Never auto-select a time slot — user must always explicitly tap to select","Never show more than 2 service options above the fold on provider detail","Never use a rating below 3 stars without a review count — it misleads without context"],"enforce":["Available time slots always shown as tappable chips — not a dropdown","Booked slots greyed and non-tappable — never hidden","Booking confirmation must show: date, time, provider, service, price — all on one screen before final confirm","Cancellation policy always visible on booking confirmation screen","5-second undo window immediately after booking confirmed — not a modal, a toast with countdown","Automated reminder shown as part of confirmation: ''We''ll remind you 24h before''","Provider response time shown on their profile — ''Usually responds in 2 hours''","No-show policy displayed at booking — never hidden in settings"]},"states":{"empty_states":[{"screen":"home_discover","trigger":"New user, no location set","ui":"Location permission prompt — explain why: ''To show providers near you''. Single CTA: ''Enable location''. Secondary: ''Enter location manually''."},{"screen":"appointments","trigger":"No bookings made yet","ui":"Calendar illustration. Message: ''No appointments yet''. CTA: ''Find a provider''. Do not show empty calendar grid."},{"screen":"provider_detail","trigger":"Provider has no availability this week","ui":"Calendar shows greyed week. Message: ''No availability this week''. Show next available date. CTA: ''See next available slot''."}],"loading_states":[{"screen":"home_discover","ui":"Skeleton provider cards — circular avatar placeholder, name 2 lines, rating bar, distance chip. Shimmer animation."},{"screen":"date_time_picker","ui":"Calendar loads immediately from cache. Time slots show skeleton chips while loading — same chip size as real slots."},{"screen":"booking_confirmation","ui":"Spinner on confirm button only. Summary visible and readable during load. Never block the summary with a full-screen loader."}],"error_flows":[{"trigger":"Selected time slot taken by another user","ui":"Full-screen modal: ''Sorry, that slot was just booked''. Show next 3 available slots inline. One-tap re-select. No form refill required."},{"trigger":"Provider cancels confirmed booking","ui":"Push notification + in-app alert. Full explanation screen: provider name, original time, reason if provided. Options: rebook same provider, find alternative, get refund."},{"trigger":"Payment fails on booking","ui":"Stay on booking screen. Red inline error on payment field. Slot held for 5 minutes — timer shown. Message: ''Slot held for 5:00. Update payment to confirm.''"},{"trigger":"Location permission denied","ui":"Manual entry field appears immediately. No error state — seamless fallback. Map-based search replaced with text search."}],"edge_cases":[{"case":"Booking for someone else","ui":"Toggle on booking form: ''Booking for myself / Someone else''. If someone else — name and contact field appears. Confirmation sent to both."},{"case":"Provider unavailable on selected date (holiday)","ui":"Calendar shows holiday marker. Tapping shows: ''Provider unavailable — public holiday''. Next available date highlighted."},{"case":"Same-day booking within cancellation window","ui":"Warning shown before confirm: ''This booking is within the [X]h cancellation window. Cancellation will incur a fee.'' Explicit acknowledgement required."},{"case":"Multi-service booking","ui":"Services stack on booking summary. Total time and total price calculated and shown. Never let stacked services exceed provider''s working hours."}]},"components":["ProviderCard","CalendarPicker","TimeSlotGrid","BookingConfirmCard","ServiceTag","AvailabilityBadge","ReviewRow"],"nav_active_states":{"home_discover":"Discover","provider_detail":"Discover","service_detail":"Discover","date_time_picker":"Discover","booking_confirmation":"Bookings","booking_success":"Bookings","appointments":"Bookings","appointment_detail":"Bookings","profile_settings":"Profile"}}'::jsonb, 1),
  ('ecommerce_core', 'E-commerce', 'Direct-to-consumer product selling platform. Industry brain defines what is sold and the visual world. This core defines how the shopping experience works.', '{}', '{"archetype_id":"ecommerce_core","archetype_name":"E-commerce","description":"Direct-to-consumer product selling platform. Industry brain defines what is sold and the visual world. This core defines how the shopping experience works.","valid_industries":["Beauty & Wellness","Retail & Fashion","Food & Beverage","Healthcare","Finance","Education","Fitness & Sport","Travel & Lifestyle","Real Estate","Transport & Logistics","Events & Ticketing","Entertainment & Media","AI & Technology","Developer Tools"],"icon_pack":{"default_library":{"name":"Lucide","variant":"Rounded line","url":"https://lucide.dev"},"industry_overrides":{"Retail & Fashion":{"name":"Remix Icons","variant":"Ultra-thin line","url":"https://remixicon.com"},"Beauty & Wellness":{"name":"Phosphor Icons","variant":"Duotone","url":"https://phosphoricons.com"}},"core_nav_icons":["home","search","shopping-bag","heart","user","bell","filter","grid","arrow-back","tag"],"core_domain_icons":["shopping-cart","heart","star","package","truck","tag","percent","gift","return","shield"]},"landing_page":{"sections":[{"id":"hero","generates_images":true},{"id":"category_entry","generates_images":true},{"id":"featured_products","generates_images":true},{"id":"cta_footer","generates_images":false}],"three_js":{"style":"rotating_geometry","description":"Clean geometric shapes — icosahedrons and torus wireframes — rotating slowly at different speeds and depths. Minimal, product-first.","intensity":"subtle","interaction":"mouse_parallax","avoid":"no status pills, no hero-stat-line, no ticker strips"}},"core_entities":{"entities":["User","Product","Variant","Category","Cart","Order","Review","Wishlist","Payment","Address","Promotion","Notification","Return"],"relationships":["Product belongs to one or more Categories","Product has many Variants (size, colour, etc.)","Cart belongs to User, contains Product Variants","Order is created from Cart, belongs to User","Order has a Payment and an Address","Order has a Status (pending, confirmed, shipped, delivered, returned)","Review belongs to User, written about a Product after Order","Wishlist belongs to User, contains Products","Promotion applies to Products, Categories, or Orders","Return belongs to Order, initiated by User","Notification belongs to User, triggered by Order status or price drop events"]},"tiers":{"mvp":{"tier":"MVP","description":"Core shopping — browse, search, product detail, cart, checkout, orders.","screen_count":9,"primary_flows":["Browse home → tap category → browse products → product detail → add to cart → checkout → order confirmation","Search product → filter results → product detail → add to cart → checkout","View orders → track order status"],"secondary_flows":["Save product to wishlist","Apply promo code at checkout","Leave product review","Share product"],"screens":[{"id":"home","name":"Home / Storefront","purpose":"Brand entry, featured products, categories, promotions","visual":"Industry brain visual. Hero banner. Category chips. Featured products grid.","entities":["Product","Category","Promotion"],"actions":["Search products","Browse categories","Tap featured product","View promotion banner","Navigate to all sections"],"copy":{"headline":"{{industry.copy_by_app_type[''E-commerce''].headline}}","cta":"{{industry.copy_by_app_type[''E-commerce''].cta}}","empty_state":"Nothing here yet — new products are on their way."}},{"id":"category_browse","name":"Category / Browse","purpose":"Product listing within a category with filters and sort","visual":"Product grid or list. Filter and sort bar. Active filter chips.","entities":["Product","Category","Variant"],"actions":["Filter by price, size, colour, rating","Sort by relevance, price, newest, bestselling","Toggle grid or list view","Tap product","Save to wishlist from card"]},{"id":"product_detail","name":"Product Detail","purpose":"Full product page — images, description, variants, reviews","visual":"Full-bleed image gallery. Variant selector. Price prominent. Reviews section. Sticky add to cart.","entities":["Product","Variant","Review","Cart"],"actions":["View image gallery","Select variant (size, colour)","Read full description","View reviews","Add to wishlist","Add to cart","Buy now","Share product"]},{"id":"cart","name":"Cart","purpose":"Review cart items before checkout","visual":"Item list with thumbnails. Variant shown. Price breakdown. Promo code. Checkout CTA.","entities":["Cart","Product","Variant","Promotion"],"actions":["View cart items","Change quantity","Change variant","Remove item","Apply promo code","View price breakdown","Proceed to checkout"],"copy":{"headline":"Your cart","cta":"Checkout","empty_state":"Your cart is empty. Start browsing to add something."}},{"id":"checkout","name":"Checkout","purpose":"Complete purchase — address, delivery, payment","visual":"Step flow. Address selector. Delivery options. Payment method. Order summary. Place order.","entities":["Order","Payment","Address","Promotion"],"actions":["Select or add address","Select delivery option","Select or add payment method","Apply promo","View order summary","Place order"]},{"id":"order_confirmation","name":"Order Confirmation","purpose":"Post-purchase confirmation with summary","visual":"Success animation. Order number. Summary. Track order CTA. Continue shopping CTA.","entities":["Order"],"actions":["View order summary","Track order","Continue shopping","Share order"]},{"id":"orders","name":"My Orders","purpose":"Order history and status tracking","visual":"Order cards with status badges and product thumbnails. Track and review CTAs.","entities":["Order","Product"],"actions":["View all orders","Filter by status","Track order","View order detail","Leave review","Initiate return"]},{"id":"wishlist","name":"Wishlist","purpose":"Saved products