nd sellers","visual":"User data table. Search and filter. User detail panel.","entities":["User","Seller"],"actions":["Search users","View user detail","Suspend account","Ban account","View transaction history"]},{"id":"api_access","name":"API Access","purpose":"Enterprise seller API keys and webhook management","visual":"API key list. Usage stats. Webhook config. Docs link.","entities":["Seller"],"actions":["Generate API key","View usage","Set up webhooks","View documentation","Revoke key"]},{"id":"profile_settings","name":"Profile & Settings","purpose":"Full account management with subscription and API settings","visual":"Comprehensive settings. Subscription section. API section.","entities":["User","Seller"],"actions":["All Startup actions","Manage subscription","API settings","Privacy controls"]},{"id":"help_centre","name":"Help Centre","purpose":"Self-serve help articles, dispute guidance, and support contact","visual":"Search bar. Article categories. Featured articles. Contact CTA.","entities":["User"],"actions":["Search help articles","Browse categories","Read article","Contact support","Initiate dispute from help"]}],"interaction_patterns":["All MVP and Startup interaction patterns","Escrow badge on protected listings — trust signal always visible","Flash sale countdown timer on relevant listings and home feed","Dispute step tracker — buyer always knows status","Admin queue cards — approve or reject with one tap","Bulk select checkbox appears on long press of listing card","API usage bar — fills as quota approaches limit","Loyalty points animate and increment on eligible purchase","Subscription perks tooltip on checkout — surfaces savings"]}},"layout":{"iphone":{"nav":"bottom_tab_5","nav_items":["Home","Search","Sell","Orders","Profile"],"content":"full_width_single_column","card_style":"2col_grid","cta":"sticky_full_width_bottom","hero":"search_bar_top_full_width","padding":"16px horizontal","image_ratio":"4:3 listing cards"},"ipad":{"nav":"sidebar_left_collapsed_icons_only","nav_items":["Home","Search","Sell","Orders","Profile"],"content":"3col_grid_centred","card_style":"3col_grid","cta":"inline_with_listing_card","hero":"search_bar_top_with_filter_row","padding":"24px horizontal","image_ratio":"4:3 listing cards 16:9 hero banner"},"desktop":{"nav":"top_navbar_with_category_mega_menu","nav_items":["Home","Categories","Sell","Orders","Profile"],"content":"4col_grid_max_1200px_centred","card_style":"4col_grid_hover_elevation","cta":"inline_button_on_card","hero":"full_width_hero_with_search_bar_centred","padding":"48px horizontal","image_ratio":"4:3 listing cards 21:9 hero"},"notes":"Two-sided layout — buyer browse and seller dashboard are distinct visual contexts. Never mix buyer and seller actions on the same screen."},"constraints":{"avoid":["Never show buyer and seller actions on the same screen simultaneously","Never use full-bleed hero text over listing photography — always use overlay with legible contrast","Never paginate listings — always infinite scroll or load more","Never show price without currency symbol","Never show a listing without at least one image — use a placeholder category illustration, never blank","Never use a modal for the full listing detail — always navigate to a dedicated screen","Never show more than 3 CTAs on any single screen","Never use red for anything other than errors, destructive actions, or out-of-stock states"],"enforce":["Search bar must be visible on every browse screen — top of screen, full width","Every listing card must show: image, title, price, rating — no exceptions","Seller earnings always shown in green","Filter count badge on filter icon when filters are active","Cart icon shows item count badge at all times when cart is non-empty","Commission or fee must be visible before checkout confirmation — never hide until payment","Sold out state must be visually distinct — greyed image, crossed price, disabled CTA","Trust signals — rating count, verified badge — must appear on every seller profile"]},"states":{"empty_states":[{"screen":"home_browse","trigger":"New user, no browsing history","ui":"Category grid with illustrated icons. Headline: ''Discover [category]''. No listings shown — avoids empty shell. CTA: ''Explore all categories''"},{"screen":"search_results","trigger":"Search returns zero results","ui":"Illustration of empty search. Message: ''No results for [query]''. Suggestions: check spelling, try broader terms, browse categories. Show 3 trending searches below."},{"screen":"orders","trigger":"No orders placed yet","ui":"Simple illustration. Message: ''No orders yet''. CTA: ''Start browsing''. Do not show empty table rows."},{"screen":"seller_dashboard","trigger":"No listings created yet","ui":"Step-by-step onboarding card: ''Create your first listing''. Progress steps: add photo, set price, publish. CTA prominent."},{"screen":"wishlist","trigger":"No saved items","ui":"Heart icon illustration. Message: ''Nothing saved yet''. CTA: ''Browse listings''. Do not show empty grid."}],"loading_states":[{"screen":"home_browse","ui":"Skeleton cards — image placeholder grey block, title 2 lines grey, price 1 line grey. Animate shimmer left to right. Show 6 skeleton cards in grid."},{"screen":"search_results","ui":"Skeleton list items — same shimmer. Show 8 items. Filter bar visible and interactive during load."},{"screen":"listing_detail","ui":"Skeleton: image top full width grey block, title 2 lines, price 1 line, seller row, then CTA button placeholder. Skeleton never taller than real content."},{"screen":"checkout","ui":"Spinner on payment button only. Never full screen spinner. Button label changes to ''Processing...'' with spinner. Background non-interactive."}],"error_flows":[{"trigger":"Payment fails at checkout","ui":"Inline error below payment method. Red border on card input. Message: ''Payment declined — please check your card details''. Retry button. Order NOT created. Cart preserved."},{"trigger":"Listing fails to publish","ui":"Toast: ''Could not publish listing''. Specific reason shown: missing image, prohibited keyword, incomplete fields. Draft auto-saved. Retry button."},{"trigger":"Image upload fails","ui":"Failed image slot shows red border and retry icon. Message: ''Upload failed''. Other images unaffected. Never silently drop the image."},{"trigger":"Network loss mid-browse","ui":"Offline banner at top: ''No internet connection''. Cached listings remain visible. New searches disabled with tooltip: ''Search unavailable offline''."}],"edge_cases":[{"case":"Seller views their own listing","ui":"Show ''Edit listing'' and ''View as buyer'' toggle. Never show ''Add to cart'' or ''Contact seller'' to the listing owner."},{"case":"Out of stock listing","ui":"Image greyed 50% opacity. Price crossed out. CTA: ''Notify me when available''. Remove from search results by default — show toggle to include."},{"case":"Listing with no reviews yet","ui":"Show ''No reviews yet'' — never show 0 stars. Stars only appear once first review exists."},{"case":"Seller account suspended","ui":"Listings show ''Currently unavailable''. No contact seller option. No purchase option. Brief neutral explanation."}]},"components":["ListingCard","SearchBar","FilterPanel","CategoryChip","CartButton","SellerBadge","PriceTag","RatingStars"],"nav_active_states":{"home_browse":"Home","category":"Search","listing_detail":"Home","seller_profile":"Search","cart":"Orders","checkout":"Orders","orders":"Orders","seller_dashboard":"Sell","create_listing":"Sell","profile_settings":"Profile"}}'::jsonb, 3),
  ('social_core', 'Social & Community', 'Social platform connecting users around shared interests, content, or identity. Industry brain defines the community context. This core defines how social interaction works.', '{}', '{"archetype_id":"social_core","archetype_name":"Social & Community","description":"Social platform connecting users around shared interests, content, or identity. Industry brain defines the community context. This core defines how social interaction works.","valid_industries":["Beauty & Wellness","Retail & Fashion","Food & Beverage","Healthcare","Finance","Education","Fitness & Sport","Travel & Lifestyle","Real Estate","Transport & Logistics","Events & Ticketing","Entertainment & Media","AI & Technology","Developer Tools"],"icon_pack":{"default_library":{"name":"Phosphor Icons","variant":"Rounded","url":"https://phosphoricons.com"},"industry_overrides":{"Retail & Fashion":{"name":"Remix Icons","variant":"Ultra-thin line","url":"https://remixicon.com"},"Fitness & Sport":{"name":"Tabler Icons","variant":"Bold line","url":"https://tabler.io/icons"},"Entertainment & Media":{"name":"Remix Icons","variant":"Bold filled","url":"https://remixicon.com"}},"core_nav_icons":["home","search","plus-circle","heart","user","bell","compass","grid","arrow-back","dots"],"core_domain_icons":["heart","comment","share","bookmark","camera","users","at-sign","trending","link","flag"]},"landing_page":{"sections":[{"id":"hero","generates_images":true},{"id":"community_preview","generates_images":true},{"id":"cta_footer","generates_images":false}],"three_js":{"style":"social_graph","description":"Connected node graph — dots linked by thin lines, nodes pulse when connections are active. Mimics a social network topology.","intensity":"medium","interaction":"mouse_attract","avoid":"no status pills, no hero-stat-line, no ticker strips"}},"core_entities":{"entities":["User","Post","Comment","Like","Follow","Group","Message","Notification","Story","Collection","Event","Report"],