n section.","entities":["User","Organisation"],"actions":["Edit profile","Change password","Organisation settings","Notification preferences","Log out"]}],"interaction_patterns":["KPI cards animate in on dashboard load — counter counts up to value","Table row hover highlights — click to open detail","Filter panel slides in from right or drops down inline","Record status badge — colour coded by status","Form validation inline — red border and message on error","Empty state on records list — clear CTA to create first record","Toast notification on save or action success"]},"startup":{"tier":"Startup","description":"Full SaaS with team management, notifications, integrations, advanced reporting, and role-based access.","screen_count":15,"primary_flows":["All MVP flows","Admin invites team member → assigns role → member logs in → sees role-based view","Connect integration → authenticate external service → data syncs → appears in dashboard","Set metric threshold → trigger fires → notification sent → user investigates","Build custom report → select metrics → visualise → share with team"],"secondary_flows":["All MVP secondary flows","Export report as PDF","Comment and tag teammate on record","Set up recurring report email","View audit log","Archive record"],"screens":[{"id":"login","name":"Login","purpose":"Secure auth with MFA","visual":"Clean. Logo. Email, password, MFA step.","entities":["User","Organisation"],"actions":["Login","MFA","SSO","Forgot password"]},{"id":"onboarding","name":"Onboarding","purpose":"Full org setup with integrations step","visual":"Steps. Org setup. Project. Team invite. Integration connect. Done.","entities":["User","Organisation","Project","Team","Integration"],"actions":["All MVP actions","Connect integration during onboarding"]},{"id":"dashboard","name":"Dashboard / Overview","purpose":"Role-based dashboard with custom metric widgets","visual":"KPI cards. Customisable widget grid. Alerts panel. Recent activity.","entities":["Metric","Record