actions","Manage webhooks","View API usage","Configure enterprise integrations"]},{"id":"api_access","name":"API Access","purpose":"API key management and developer documentation","visual":"API key list. Usage chart. Rate limit indicator. Docs link.","entities":["Organisation","User"],"actions":["Generate API key","View usage","Set rate limits","View documentation","Revoke key"]},{"id":"notifications","name":"Notifications","purpose":"All alerts with team digest and executive summary","visual":"All notifications. Team digest. Executive summary option.","entities":["Notification","Record","Metric"],"actions":["All Startup actions","View team digest","View executive summary"]},{"id":"notification_settings","name":"Notification Settings","purpose":"Advanced notification routing with team digest and digest schedule","visual":"Trigger matrix. Team digest schedule. Escalation rules.","entities":["Notification","User"],"actions":["All Startup actions","Set escalation rules","Configure digest schedule"]},{"id":"audit_log","name":"Audit Log","purpose":"Full compliance audit log with data export for regulators","visual":"Comprehensive log. Compliance export. Retention policy indicator.","entities":["AuditLog","User","Record"],"actions":["All Startup actions","Export compliance report","Set retention policy"]},{"id":"compliance","name":"Compliance Centre","purpose":"GDPR, SOC2, and other compliance management","visual":"Compliance status cards. Data subject requests. Retention policies. Audit reports.","entities":["Organisation","User"],"actions":["View compliance status","Process data subject request","Set retention policies","Download compliance report","View certifications"]},{"id":"white_label","name":"White-Label Settings","purpose":"Custom branding, domain, and email configuration","visual":"Brand settings. Logo upload. Colour picker. Custom domain. Email templates.","entities":["Organisation"],"actions":["Upload logo","Set brand colours","Configure custom domain","Set email templates","Preview white-label"]},{"id":"settings","name":"Settings","purpose":"Enterprise settings hub","visual":"Settings sidebar. All sections. Compliance. White-label. SSO. Data.","entities":["User","Organisation","Subscription"],"actions":["All Startup actions","SSO configuration","White-label settings","Compliance settings","Data residency"]},{"id":"billing","name":"Billing & Subscription","purpose":"Enterprise billing with usage-based and contract support","visual":"Enterprise plan card. Usage meters. Contract info. Invoice history.","entities":["Subscription","Organisation"],"actions":["View enterprise plan","View usage meters","Download invoices","Contact sales for contract"]},{"id":"admin_dashboard","name":"Super Admin Dashboard","purpose":"Platform-level admin — all orgs, revenue, health","visual":"Org table. Revenue chart. Health indicators. Support queue.","entities":["Organisation","User"],"actions":["View all orgs","View platform revenue","View health metrics","Access org as admin","View support queue"]},{"id":"custom_fields","name":"Custom Fields","purpose":"Define custom fields for records across the organisation","visual":"Field type selector. Preview. Assign to record type. Required toggle.","entities":["Record","Organisation"],"actions":["Create custom field","Select field type","Assign to record type","Set required","Reorder fields","Delete field"]},{"id":"help_centre","name":"Help Centre","purpose":"Self-serve help with admin and developer sections","visual":"Search. User, admin, and developer categories. API docs link.","entities":["User"],"actions":["Search","Browse categories","Developer docs","Contact enterprise support"]},{"id":"embedded_dashboard","name":"Embedded Dashboard","purpose":"Share read-only dashboard externally without login","visual":"Clean dashboard view. No nav. Powered by badge. Embed code.","entities":["Metric","Report"],"actions":["View embedded dashboard","Filter if allowed","Export if allowed"]}],"interaction_patterns":["All MVP and Startup interaction patterns","Workspace switcher — dropdown from top nav, switches context instantly","Automation builder — drag nodes on canvas, connect with arrows","Permission matrix — checkbox grid, rows are features, columns are roles","API usage bar — fills as quota approaches, turns amber then red","Compliance status card — green tick, amber warning, red alert","White-label preview — live render updates as user changes brand settings","Custom field drag to reorder — handle on left of field row","Directory sync status — last synced time, manual sync button"]}},"layout":{"iphone":{"nav":"bottom_tab_4","nav_items":["Dashboard","Records","Reports","Settings"],"content":"full_width_single_column_stacked_cards","card_style":"full_width_kpi_cards_stacked","cta":"floating_action_button_bottom_right","hero":"kpi_cards_stacked_then_chart","padding":"16px horizontal","image_ratio":"no_photography_charts_only"},"ipad":{"nav":"sidebar_left_collapsed_icons_with_labels_on_hover","nav_items":["Dashboard","Records","Reports","Team","Settings"],"content":"2col_kpi_grid_then_full_width_charts","card_style":"2col_kpi_grid","cta":"top_right_primary_action_button","hero":"2col_kpi_row_then_chart_below","padding":"24px","image_ratio":"no_photography_charts_only"},"desktop":{"nav":"sidebar_left_fixed_expanded_with_section_groups","nav_items":["Dashboard","Records","Reports","Analytics","Team","Settings"],"content":"left_anchored_max_1440px_with_sidebar","card_style":"4col_kpi_row_then_2col_charts","cta":"top_right_header_area_primary_button","hero":"4col_kpi_cards_row_full_width_chart_below","padding":"32px content area","image_ratio":"no_photography_data_viz_only"},"notes":"Data density is a feature not a bug. Sidebar always present on desktop — never hamburger on desktop. On iPhone sidebar becomes bottom tab — never a hamburger either."},"constraints":{"avoid":["Never use a bottom tab nav on desktop — sidebar only","Never use photography or lifestyle imagery anywhere in the product","Never use a pie chart for more than 4 categories — use a bar chart instead","Never truncate KPI card numbers — show full value or use abbreviation (10.2K) never ellipsis","Never use red for anything except error states and negative trends — it triggers alarm","Never put more than 5 items in the sidebar primary nav","Never use a modal for record creation — use a side panel or dedicated screen","Never auto-refresh data without warning — always show ''Last updated X ago'' with manual refresh","Never use gradients on charts — flat fills only for clarity"],"enforce":["KPI cards always show: metric name, value, trend indicator (up/down arrow), percentage change","Trend up in green, trend down in red — no exceptions in B2B data context","Table rows always have hover state — subtle background shift","Pagination or infinite scroll on all tables — never show all rows without limit","Filter and sort always accessible without leaving the current screen","Export button always present on any table or chart — CSV minimum","Role-based access states — admin sees everything, viewer sees read-only, manager sees subset","All timestamps in user''s local timezone — never UTC without conversion","Search available on every records list — keyboard shortcut Cmd/Ctrl+K"]},"states":{"empty_states":[{"screen":"dashboard","trigger":"New account, no data yet","ui":"KPI cards show with placeholder values and ''Connect your data'' CTA. Chart areas show illustrated placeholder with setup instructions. Never show zero values as if they''re real."},{"screen":"records_list","trigger":"No records created yet","ui":"Table shows column headers. Body shows single row with illustration and: ''No [records] yet''. CTA: ''Create your first [record]''. Import option shown secondary."},{"screen":"reports","trigger":"No data in selected date range","ui":"Chart area shows: ''No data for this period''. Date range selector highlighted. Suggest adjacent period with data available."},{"screen":"records_list","trigger":"Search or filter returns no results","ui":"Empty state inline in table: ''No results match your filters''. Show active filters above with ''Clear all'' option. Never collapse the filter bar."}],"loading_states":[{"screen":"dashboard","ui":"KPI cards load first with skeleton shimmer — same size as real cards. Charts below load after — skeleton rectangle in chart area. Data table skeleton: column headers visible, 5 row skeletons below."},{"screen":"records_list","ui":"Table header and filter bar visible and interactive immediately. Rows show skeleton shimmer. Page count shows skeleton."},{"screen":"report_detail","ui":"Chart skeleton — grey rectangle exact size of chart. Data table skeleton below. Never show old data during reload — always show skeleton."}],"error_flows":[{"trigger":"Data sync fails","ui":"Banner at top of dashboard: ''Data sync failed — showing data from [time]''. Retry button inline. KPI values shown with warning icon indicating they may be stale."},{"trigger":"Record save fails","ui":"Form remains open. Red inline error at top of form. Specific field errors shown inline. Data not lost — user can retry or copy content."},{"trigger":"Export fails","ui":"Toast: ''Export failed. Please try again.'' Retry button in toast. If large export — offer to email when ready instead."},{"trigger":"Permission denied on action","ui":"Action button shows with lock icon. Clicking shows tooltip: ''You need [role] access to do this. Contact your admin.'' Never show a generic 403 page."}],"edge_cases":[{"case":"Very large dataset (100k+ rows)","ui":"Pagination enforced. Page size selector: 25/50/100 rows. Server-side search — not client-side filter. Export shows warning: ''Large export may take a few minutes''."},{"case":"Multiple users editing same record","ui":"Optimistic lock — last save wins. Conflict notification: ''[User] also edited this record. Your changes were saved.'' Show diff option."},{"case":"Chart with single data point","ui":"Show as a KPI card instead of a chart. A chart with one point is meaningless — degrade gracefully."},{"case":"Negative KPI value","ui":"Show negative sign clearly. Red colour. Down arrow. Never use parentheses for negative — use minus sign."}]},"components":["KPICard","DataTable","ChartContainer","FilterBar","StatusBadge","ExportButton","DateRangePicker","RecordRow"],"nav_active_states":{"login":"Dashboard","onboarding":"Dashboard","dashboard":"Dashboard","records_list":"Records","record_detail":"Records","create_edit_record":"Records","reports":"Reports","settings":"Settings"}}'::jsonb, 5),
  ('chat_core', 'Chat / Messaging', 'Real-time communication platform. Industry brain defines the context and purpose of communication. This core defines how messaging, channels, and real-time interaction work.', '{}', '{"archetype_id":"chat_core","archetype_name":"Chat / Messaging","description":"Real-time communication platform. Industry brain defines the context and purpose of communication. This core defines how messaging, channels, and real-time interaction work.","valid_industries":["Beauty & Wellness","Retail & Fashion","Food & Beverage","Healthcare","Finance","Education","Fitness & Sport","Travel & Lifestyle","Real Estate","Transport & Logistics","Events & Ticketing","Entertainment & Media","AI & Technology","Developer Tools"],"icon_pack":{"default_library":{"name":"Lucide","variant":"Rounded line","url":"https://lucide.dev"},"industry_overrides":{"Healthcare":{"name":"Material Symbols","variant":"Rounded","url":"https://fonts.google.com/icons"}},"core_nav_icons":["home","message-circle","phone","user","bell","settings","search","plus","arrow-back","dots"],"core_domain_icons":["message-circle","phone","video","mic","mic-off","camera-off","paperclip","smile","send","check-check"]},"landing_page":{"sections":[{"id":"hero","generates_images":false},{"id":"security_section","generates_images":false},{"id":"cta_footer","generates_images":false}],"three_js":{"style":"message_particles","description":"Small rectangular particles drifting upward like message bubbles floating. Clusters form and dissolve. Minimal and clean.","intensity":"very_subtle","interaction":"mouse_parallax","avoid":"no status pills, no hero-stat-line, no ticker strips"}},"core_entities":{"entities":["User","Conversation","Message","Channel","Attachment","Reaction","Notification","Contact","Group","Call","Status","Bot"],"relationships":["User has many Conversations","Conversation is between two or more Users","Message belongs to Conversation, sent by User","Channel is a group Conversation with a