. Status with expiry. Timezone. Pronouns. Contact info.","entities":["User"],"actions":["Set custom status with expiry","Set timezone","Add pronouns","Edit contact info"]},{"id":"settings","name":"Settings","purpose":"Enterprise settings with accessibility, theme, and security","visual":"Full settings sidebar. Theme. Accessibility. Two-factor. Devices. Privacy.","entities":["User"],"actions":["All Startup actions","Theme settings","Accessibility settings","Manage trusted devices","Two-factor settings"]}],"interaction_patterns":["All MVP and Startup interaction patterns","Slash command autocomplete — / triggers command list in input","Breakout room assignment — drag and drop members into rooms","Screen share request — permission overlay on recipient screen","Meeting transcription indicator — live text scrolls during call","Integration post — distinct visual style in channel — app icon + formatted message","Retention policy banner on channel — messages delete after X days indicator","Workflow trigger button on message — action button below message","Custom status — emoji + text + expiry time — shows next to name everywhere"]}},"layout":{"iphone":{"nav":"bottom_tab_4","nav_items":["Messages","Contacts","Profile","Settings"],"content":"full_width_conversation_list_then_thread","card_style":"conversation_row_avatar_left_preview_right","cta":"compose_button_top_right","hero":"search_bar_top_then_conversation_list","padding":"0px list rows 16px message bubbles","image_ratio":"1:1 avatar"},"ipad":{"nav":"sidebar_left_fixed","nav_items":["Messages","Contacts","Profile","Settings"],"content":"split_left_conversation_list_right_active_thread","card_style":"compact_conversation_row","cta":"compose_button_in_sidebar_header","hero":"split_view_list_and_thread_always_visible","padding":"0px","image_ratio":"1:1 avatar"},"desktop":{"nav":"sidebar_left_fixed_with_section_groups","nav_items":["Messages","Channels","Contacts","Profile","Settings"],"content":"3col_nav_left_list_centre_thread_right","card_style":"compact_conversation_row_selected_state","cta":"compose_button_top_of_list_column","hero":"3col_always_visible_no_navigation_transitions","padding":"0px columns 16px thread padding","image_ratio":"1:1 avatar"},"notes":"Input bar must always be above keyboard on iPhone — never hidden. On iPad and desktop the thread and list are always simultaneously visible — never full-screen navigate away from list."},"constraints":{"avoid":["Never use pagination in a chat thread — always infinite scroll upward to load history","Never show timestamps on every message — show time at start of each day cluster only","Never use a modal for attachments — inline attachment preview in the message bubble","Never show typing indicator for more than 30 seconds — it becomes noise","Never auto-mark messages as read until the conversation is opened and scrolled to","Never use red bubbles for sent messages — red is exclusively for errors","Never truncate message preview in conversation list to less than 1 line","Never show a send button that is active on an empty input"],"enforce":["Message status: single tick = sent, double tick = delivered, filled double tick = read","Typing indicator — animated dots — appears within 1 second of other user typing","Input bar always above keyboard — never hidden when keyboard is open","Swipe right on message to reply — quoted message appears in input","Long press opens context menu: reply, react, copy, delete, forward","Unread count badge on conversation row — disappears when conversation opened","Online status indicator — green dot on avatar when online","Message sent sound/haptic — subtle, respects device settings"]},"states":{"empty_states":[{"screen":"conversations","trigger":"No conversations yet","ui":"Message bubble illustration. Message: ''No messages yet''. CTA: ''Start a conversation''. Secondary: ''Find contacts''."},{"screen":"chat","trigger":"New conversation, no messages","ui":"Contact name and avatar centred. First message prompt: ''Say hello to [name]''. Input bar ready and focused. No empty thread lines."},{"screen":"search","trigger":"Message search returns no results","ui":"Message: ''No messages found for [query]''. Suggestions: check spelling, search in different conversation."}],"loading_states":[{"screen":"conversations","ui":"Skeleton conversation rows — avatar circle, name line, preview line, time stamp right. 5 skeleton rows shimmer."},{"screen":"chat","ui":"History loads from bottom — skeleton bubbles appear at top while scrolling up. New messages always appear at bottom immediately."},{"screen":"media","ui":"Image messages show placeholder with spinner while loading. Tap to retry if failed. Video shows thumbnail immediately, stream on play."}],"error_flows":[{"trigger":"Message fails to send","ui":"Message bubble shows red warning icon right side. Tap warning: ''Message failed to send''. Options: Retry, Delete. Never silently drop the message."},{"trigger":"User blocked by recipient","ui":"Messages show single tick only — never delivered. No error shown to sender — privacy protection. Input remains active."},{"trigger":"Attachment too large","ui":"Inline error before sending: ''File too large. Maximum [size]''. File not attached. Other message content preserved."},{"trigger":"No internet during send","ui":"Message queued with clock icon. ''Sending when connected...'' status. Auto-sends when connection restored. Never lost."}],"edge_cases":[{"case":"Very long message (500+ characters)","ui":"Message bubble wraps naturally. No character limit shown during compose unless approaching limit. Read more not needed in chat — show full message."},{"case":"Group with 50+ members","ui":"Member list paginated. Typing indicator shows ''[Name] and 2 others are typing'' — not all names. Read receipts show count not all avatars."},{"case":"Message edited after sending","ui":"Message shows ''Edited'' label with edit timestamp. Original message not shown. Edit history accessible by long press."},{"case":"Voice message playback","ui":"Waveform visualisation in bubble. Playback position scrubable. Speed control: 1x 1.5x 2x. Duration shown before and during playback."}]},"components":["MessageBubble","ConversationRow","TypingIndicator","InputBar","AttachButton","ReadReceipt","OnlineDot"],"nav_active_states":{"conversations":"Messages","chat":"Messages","new_conversation":"Messages","group_info":"Messages","contact_profile":"Contacts","search":"Messages","profile":"Profile","settings":"Settings"}}'::jsonb, 6),
  ('streaming_core', 'Content & Streaming', 'On-demand content consumption platform. Industry brain defines what type of content is consumed. This core defines how content discovery, playback, and progression work.', '{}', '{"archetype_id":"streaming_core","archetype_name":"Content & Streaming","description":"On-demand content consumption platform. Industry brain defines what type of content is consumed. This core defines how content discovery, playback, and progression work.","valid_industries":["Beauty & Wellness","Retail & Fashion","Food & Beverage","Healthcare","Finance","Education","Fitness & Sport","Travel & Lifestyle","Real Estate","Transport & Logistics","Events & Ticketing","Entertainment & Media","AI & Technology","Developer Tools"],"icon_pack":{"default_library":{"name":"Remix Icons","variant":"Bold filled","url":"https://remixicon.com"},"industry_overrides":{"Education":{"name":"Phosphor Icons","variant":"Rounded","url":"https://phosphoricons.com"},"Fitness & Sport":{"name":"Tabler Icons","variant":"Bold line","url":"https://tabler.io/icons"}},"core_nav_icons":["home","search","play","heart","user","bell","library","compass","arrow-back","more"],"core_domain_icons":["play","pause","skip-forward","volume","download","bookmark","share","heart","star","fullscreen"]},"landing_page":{"sections":[{"id":"hero","generates_images":true},{"id":"content_preview","generates_images":true},{"id":"pricing","generates_images":false},{"id":"cta_footer","generates_images":false}],"three_js":{"style":"flowing_wave","description":"Smooth undulating wave mesh in the background. Content-first energy. Wave responds slowly to mouse position.","intensity":"subtle","interaction":"mouse_wave_distort","avoid":"no status pills, no hero-stat-line, no ticker strips"}},"core_entities":{"entities":["User","Content","Series","Episode","Category","Playlist","Progress","Subscription","Download","Review","Creator","Notification"],"relationships":["Content belongs to a Creator","Content belo