directions_button_in_bottom_sheet","hero":"full_screen_map_search_bar_floating_top","padding":"16px bottom sheet content","image_ratio":"16:9 place photo in sheet"},"ipad":{"nav":"sidebar_left_overlays_map_left_edge","nav_items":["Search","Saved","Directions","Profile"],"content":"map_fills_remaining_space_right_of_sidebar","card_style":"list_in_sidebar_with_map_pins_synced","cta":"directions_in_sidebar_detail_view","hero":"map_dominant_sidebar_list_secondary","padding":"16px sidebar","image_ratio":"4:3 place photo in sidebar"},"desktop":{"nav":"sidebar_left_fixed","nav_items":["Search","Explore","Saved places","Directions","Profile"],"content":"sidebar_left_fixed_map_fills_rest","card_style":"list_card_in_sidebar_synced_with_map_highlight","cta":"get_directions_prominent_in_detail_panel","hero":"map_always_fills_right_panel_never_hidden","padding":"24px sidebar panels","image_ratio":"16:9 place photo"},"notes":"The map is the product — it must never be hidden or collapsed. Everything else is an overlay or sidebar. Current location button always visible floating on the map."},"constraints":{"avoid":["Never replace the map with a list view as the default — map is always primary","Never show a bottom sheet that covers more than 65% of the map","Never use text labels on map pins for dense areas — use icons only, expand on tap","Never auto-start navigation without user explicitly tapping ''Start navigation''","Never show ETA without updating it in real time during navigation","Never use blue for anything other than the user''s current location indicator","Never cluster pins beyond 3 levels of zoom aggregation — show individual pins at street level","Never hide the current location button — always visible on map overlay"],"enforce":["Current location always shown as pulsing blue dot — never static","Current location button always visible — tap to re-centre map","Place detail always slides up from bottom — map stays visible behind","Pins cluster at low zoom — number shows count inside cluster","Category filter chips always visible above the map — horizontal scroll","Search bar always at top of map screen — even in navigation mode","Distance always shown in user''s preferred unit (km/miles) — set in settings","Offline map indicator when no connection — show last downloaded area boundaries"]},"states":{"empty_states":[{"screen":"map_home","trigger":"Location permission denied","ui":"Map shows default city view (not user location). Banner: ''Enable location for nearby results''. CTA: ''Enable location''. Search remains fully functional."},{"screen":"search_results","trigger":"No places in area match category","ui":"Map shows search area with no pins. Bottom sheet: ''No [category] found here''. CTA: ''Expand search area''. Show radius slider."},{"screen":"saved_places","trigger":"No saved places","ui":"Bookmark illustration. Message: ''No saved places yet''. Instruction: ''Tap the bookmark icon on any place to save it''. CTA: ''Explore map''."}],"loading_states":[{"screen":"map_home","ui":"Map tiles load progressively — grey tiles replaced as they load. Pins appear after tiles in area loaded. Skeleton bottom sheet while place data loads."},{"screen":"place_detail","ui":"Bottom sheet slides up immediately with skeleton content. Photo skeleton top, name skeleton, meta row skeleton. Real content replaces as loaded."},{"screen":"navigation_active","ui":"Route line appears first. Turn-by-turn instructions load within 1 second. ETA shows ''Calculating...'' then updates. Never block navigation on slow data."}],"error_flows":[{"trigger":"Route calculation fails","ui":"Banner: ''Could not calculate route''. Options: Try different transport mode, Check endpoints, Try again. Map still interactive during error."},{"trigger":"GPS signal lost during navigation","ui":"Banner: ''GPS signal lost — last known position shown''. Pulsing dot becomes grey. Instructions paused. Auto-resumes when signal returns."},{"trigger":"Place data unavailable","ui":"Place pin still tappable. Bottom sheet shows: ''Details unavailable for this location''. Show coordinates. Option to report as inaccurate."},{"trigger":"Offline — map area not downloaded","ui":"Grey tiles for undownloaded areas. Banner: ''Offline — some areas unavailable''. Download prompt for current area. Cached areas fully functional."}],"edge_cases":[{"case":"Navigation in tunnel (no GPS)","ui":"Dead reckoning — continue showing estimated position based on last known speed and direction. ''Estimating position'' indicator. Resume GPS on exit."},{"case":"Multiple pins at exact same location","ui":"Stack indicator — top pin shows +N badge. Tap to expand into a list of places at that location. Never collapse all into one unnavigable cluster."},{"case":"Long place name on pin label","ui":"Truncate label to 15 characters on pin. Full name shown in bottom sheet. Never let pin label overlap adjacent pins."},{"case":"Place permanently closed","ui":"Pin shown with grey overlay. ''Permanently closed'' label in bottom sheet. Remove from active search results. Keep in saved places with closure notice."}]},"components":["MapPin","PlaceCard","SearchOverlay","DirectionsButton","BottomSheet","ClusterBadge","ETAChip"],"nav_active_states":{"map_home":"Map","place_detail":"Map","search":"Search","directions":"Map","navigation_active":"Map","saved_places":"Saved","profile":"Profile","settings":"Profile"}}'::jsonb, 8),
  ('ai_core', 'AI Tool', 'AI-powered product where the AI is the core experience. Industry brain defines the domain the AI operates in. This core defines how AI interaction, generation, and configuration work.', '{}', '{"archetype_id":"ai_core","archetype_name":"AI Tool","description":"AI-powered product where the AI is the core experience. Industry brain defines the domain the AI operates in. This core defines how AI interaction, generation, and configuration work.","valid_industries":["Beauty & Wellness","Retail & Fashion","Food & Beverage","Healthcare","Finance","Education","Fitness & Sport","Travel & Lifestyle","Real Estate","Transport & Logistics","Events & Ticketing","Entertainment & Media","AI & Technology","Developer Tools"],"icon_pack":{"default_library":{"name":"Lucide","variant":"Rounded line","url":"https://lucide.dev"},"industry_overrides":{},"core_nav_icons":["home","plus-circle","clock","bookmark","user","settings","key","layers","arrow-back","menu"],"core_domain_icons":["cpu","sparkles","zap","copy","refresh-cw","thumbs-up","thumbs-down","stop-circle","send","paperclip"]},"landing_page":{"sections":[{"id":"hero","generates_images":false},{"id":"how_it_works","generates_images":false},{"id":"pricing","generates_images":false},{"id":"cta_footer","generates_images":false}],"three_js":{"style":"neural_network","description":"Multi-layer neural network — nodes connected by edges, signal pulses travel along connections. Nodes activate and dim. Technical and precise.","intensity":"medium","interaction":"mouse_parallax","avoid":"no status pills, no hero-stat-line, no ticker strips"}},"core_entities":{"entities":["User","Conversation","Message","Generation","Prompt","Model","Usage","APIKey","Project","Template","Output","Feedback"],"relationships":["User owns many Conversations","Conversation contains many Messages","Message is either from User or from AI","Generation is the AI output from a Message or Prompt","Prompt is a saved input created by User","Model is the AI model configuration — version, temperature, context length","Usage tracks tokens consumed and cost per User or Organisation","APIKey belongs to User or Organisation — grants programmatic access","Project groups Conversations by topic or purpose","Template is a reusable Prompt created by User","Output is a saved Generation — image, text, code, or file","Feedback belongs to Message — thumbs up or down plus optional note"]},"tiers":{"mvp":{"tier":"MVP","description":"Core AI interaction — chat with AI, get generations, view history.","screen_count":8,"primary_flows":["Sign up → start new conversation → type prompt → receive AI generation → continue conversation","View conversation history → open past conversation → continue from where left off","View usage → check remaining credits"],"secondary_flows":["Copy AI output","Regenerate response","Give feedback on response","Share conversation link"],"screens":[{"id":"home","name":"Home / New Chat","purpose":"Start new conversation — prompt entry and quick start options","visual":"Clean dark interface. Prompt input bar at centre or bottom. Quick start prompts. Model indicator.","entities":["Conversation","Message","Model"],"actions":["Type prompt","Start new conversation","Select quick start prompt","View recent conversations","Select model"],"copy":{"headline":"{{industry.copy_by_app_type[''AI Tool''].headline}}","cta":"{{industry.copy_by_app_type[''AI Tool''].cta}}","empty_state":"Start a conversation — your history will appear here."}},{"id":"conversation","name":"Conversation / Chat","purpose":"Active AI conversation — messages, generations, and controls","visual":"Message thread. User bubbles right. AI response left with avatar. Streaming text. Input bar.","entities":["Conversation","Message","Generation","Feedback"],"actions":["Send message","Regenerate response","Copy response","Give thumbs up or down","Attach file or image","Stop generation","Edit user message"]},{"id":"history","name":"Conversation History","purpose":"All past conversations — search and resume","visual":"Conversation list with title and date. Search bar. Delete option.","entities":["Conversation","User"],"actions":["Browse all conversations","Search conversations","Open conversation","Delete conversation","Rename conversation"],"copy":{"headline":"Your conversations","cta":"New chat","empty_state":"No past conversations yet. Start your first one."}},{"id":"saved_outputs","name":"Saved Outputs","purpose":"Outputs the user has saved for later use","visual":"Output cards grid. Type indicator — text, code, image. Copy and share.","entities":["Output","Generation"],"actions":["View saved outputs","Copy output","Share output","Delete output","Filter by type"]},{"id":"usage","name":"Usage & Credits","purpose":"Current usage, remaining credits, and usage history","visual":"Credits bar. Used vs remaining. Usage history chart. Upgrade CTA.","entities":["Usage","User"],"actions":["View credit balance","View usage history","View usage breakdown","Upgrade plan"]},{"id":"settings_model","name":"Model Settings","purpose":"Select AI model and configure parameters","visual":"Model selector. Temperature slider. Max tokens. System prompt input.","entities":["Model","User"],"actions":["Select model","Adjust temperature","Set max tokens","Set system prompt","Reset to defaults"]},{"id":"profile","name":"Profile","purpose":"User profile and account management","visual":"Avatar. Name. Email. Account settings link.","entities":["User"],"actions":["View profile","Edit name","Change password","Manage account"]},{"id":"settings","name":"Settings","purpose":"App settings — theme, language, account, notifications","visual":"Settings list. Theme toggle. Language. Account section.","entities":["User"],"actions":["Toggle theme","Select language","Account settings","Notification settings","Log out"]}],"interaction_patterns":["Streaming text output — AI response types character by character","Stop generation button appears during streaming","Copy button appears on hover or tap of any AI message","Regenerate button below each AI response","Conversation auto-titled from first message","Input bar expands vertically as user types multi-line prompt","Code blocks in responses — syntax highlighted, copy button in corner","Feedback thumbs — up fills green, down fills red on tap"]},"startup":{"tier":"Startup","description":"Full AI tool with prompt library, projects, file uploads, image generation, and team sharing.","screen_count":14,"primary_flows":["All MVP flows","Create project → organise conversations → set project-level system prompt → generate within project context","Upload file or image → reference in prompt → AI analyses and responds","Use prompt template → customise variables → send → save output","Share conversation or output → recipient views without account"],"secondary_flows":["All MVP secondary flows","Create and save custom template","Set up custom persona or assistant","Export conversation as PDF or markdown","Browse public template library"],"screens":[{"id":"home","name":"Home / New Chat","purpose":"Personalised home with projects, recent, and prompt suggestions","visual":"Recent conversations. Projects row. Prompt suggestions by use case. New chat CTA.","entities":["Conversation","Message","Model","Project"],"actions":["All MVP actions","View projects","Start conversation in project","View prompt suggestions by category"],"copy":{"headline":"{{industry.copy_by_app_type[''AI Tool''].headline}}","cta":"{{industry.copy_by_app_type[''AI Tool''].cta}}","empty_state":"Start a conversation — your history will appear here."}},{"id":"conversation","name":"Conversation / Chat","purpose":"Rich conversation with file uploads, image generation, and branching","visual":"Thread. File attachment previews. Image generations inline. Branch conversation option.","entities":["Conversation","Message","Generation","Feedback"],"actions":["All MVP actions","Upload file","Upload image","Generate image from 