tom models","Deploy model","Set model as org default","View model performance","Archive model"]},{"id":"model_fine_tuning","name":"Model Fine-Tuning","purpose":"Upload training data and fine-tune a custom model","visual":"Step flow. Data upload. Training config. Progress. Evaluation. Deploy.","entities":["Model","User"],"actions":["Upload training data","Set training parameters","Start fine-tuning","Monitor progress","Evaluate model","Deploy model"]},{"id":"usage_admin","name":"Usage & Cost Management","purpose":"Org-wide usage dashboard with per-user limits and cost forecast","visual":"Total spend chart. Per-user usage table. Budget alert. Cost forecast. Limits.","entities":["Usage","User"],"actions":["View org usage","View per-user usage","Set per-user limits","Set budget alert","View cost forecast","Export billing report"]},{"id":"team_management","name":"Team Management","purpose":"Manage org members, roles, and workspace access","visual":"Member table. Role badge. Usage per member. Invite. Deactivate.","entities":["User"],"actions":["Invite member","Assign role","View member usage","Set per-member limits","Deactivate member"]},{"id":"compliance","name":"Compliance & Audit","purpose":"Conversation logs, data export, and compliance reporting","visual":"Log table. Filter by user, date, model. Export CTA. Retention policy.","entities":["Conversation","Message","User"],"actions":["View conversation logs","Filter logs","Export logs","Set retention policy","Download compliance report"]},{"id":"sso_settings","name":"SSO & Security Settings","purpose":"Configure enterprise SSO and security policies","visual":"SSO provider setup. Policy settings. Session length. IP restrictions.","entities":["User"],"actions":["Configure SSO provider","Set session length","Set IP allowlist","Enable MFA requirement","View active sessions"]},{"id":"history","name":"Conversation History","purpose":"Full history with team filter and compliance view","visual":"History. Team filter. Compliance