ion.","entities":["Project","Log","User"],"actions":["View compliance status","Download audit report","View evidence","Set data retention","View certifications"]},{"id":"domains","name":"Domains & Infrastructure","purpose":"Custom domains, CDN, and infrastructure settings","visual":"Domain list. CDN config. Custom infrastructure settings. SSL.","entities":["Project","Deployment"],"actions":["All Startup actions","Configure CDN","Custom infrastructure settings"]},{"id":"admin_dashboard","name":"Admin / Super Admin Dashboard","purpose":"Platform-level — all workspaces, usage, health, support","visual":"Workspace table. Platform health. Build queue. Support tickets. Revenue.","entities":["Project","User","Build"],"actions":["View all workspaces","View platform health","Access workspace as admin","View support queue","View platform revenue"]},{"id":"sso_settings","name":"SSO & Security Settings","purpose":"Enterprise SSO, MFA policy, and session management","visual":"SSO provider config. MFA enforcement toggle. Session policies. IP restrictions.","entities":["User"],"actions":["Configure SSO provider","Enforce MFA org-wide","Set session timeout","Configure IP allowlist"]},{"id":"usage","name":"Usage & Billing","purpose":"Enterprise billing with contract and committed use discounts","visual":"Enterprise plan. Committed use progress. Cost allocation. Invoices. Contact sales.","entities":["Usage","Project"],"actions":["View committed use progress","View cost allocation","Download invoices","Contact enterprise sales"]},{"id":"settings","name":"Settings","purpose":"Enterprise settings hub — all sections","visual":"Settings sidebar. All enterprise sections. Compliance. SSO. Cost. Infra.","entities":["User","Project"],"actions":["All Startup actions","Compliance settings","SSO configuration","Cost allocation settings","Infrastructure settings"]}],"interaction_patterns":["All MVP and Startup interaction patterns","Pipeline canvas — drag stage blocks to reorder — connect with lines","Approval gate — pending state blocks pipeline — reviewer sees approve or reject","Multi-region traffic slider — adjusts in real time — must total 100%","Canary deployment indicator — percentage badge on deployment card","SLO compliance gauge — circular gauge — green above threshold, red below","Permission matrix — checkbox grid — rows resources, columns roles","Audit log row — expand to full action JSON — copy JSON button","Cost chart — hover to see exact amount — click to drill down to project","SSO sync indicator — last synced time + manual sync button"]}},"layout":{"iphone":{"nav":"bottom_tab_4","nav_items":["Dashboard","Projects","Logs","Settings"],"content":"full_width_single_column_data_dense","card_style":"full_width_project_status_row","cta":"top_right_action_button","hero":"status_badges_and_build_list","padding":"16px horizontal","image_ratio":"no_photography_status_icons_only"},"ipad":{"nav":"sidebar_left_with_labels","nav_items":["Dashboard","Projects","Deployments","Logs","API Keys","Settings"],"content":"2col_layout_list_left_detail_right","card_style":"compact_project_row_with_status_badge","cta":"top_right_primary_action","hero":"project_list_with_detail_panel_right","padding":"24px","image_ratio":"no_photography"},"desktop":{"nav":"sidebar_left_fixed_with_section_groups","nav_items":["Dashboard","Projects","Deployments","Logs","Analytics","API Keys","Docs","Settings"],"content":"left_anchored_max_1440px_with_sidebar","card_style":"data_table_rows_with_status_and_actions","cta":"top_right_header_new_project_button","hero":"full_width_status_overview_then_project_table","padding":"32px content","image_ratio":"no_photography_monospace_code_only"},"notes":"Monospace font for all code, logs, and terminal output — no exceptions. Copy button on every code block, API key, and command. Build status always visible — never buried."},"constraints":{"avoid":["Never use photography, illustration, or decorative elements anywhere","Never use a rounded bubble UI — developer tools use sharp or minimal radius","Never paginate logs — always infinite scroll with search and filter","Never auto-refresh without showing a refresh indicator and timestamp","Never hide the raw request/response — always offer a way to see raw data","Never use a modal for log viewing — always navigate to a dedicated log screen","Never truncate error messages — full error always accessible","Never use colour alone to convey status — always pair with icon and label"],"enforce":["Build status: spinner = building, green check = success, red X = failed — always these exact patterns","Log lines in monospace font — always","Error lines in logs always red background highlight","New log lines auto-scroll to bottom — with manual scroll-lock toggle","API key always partially masked — first 4 and last 4 chars visible, rest masked","Copy to clipboard on every code snippet and API key — keyboard shortcut supported","Uptime shown as percentage with 2 decimal places — 99.98% not ''high''","Deploy time shown precisely — ''2m 34s'' not ''about 3 minutes''"]},"states":{"empty_states":[{"screen":"dashboard","trigger":"No projects created yet","ui":"Code terminal illustration (minimal SVG). Message: ''No projects yet''. CTA: ''Create your first project''. Show CLI command as alternative: ''or run [command] to get started''."},{"screen":"logs","trigger":"No logs for this project yet","ui":"Terminal cursor blinking. Message: ''No logs yet. Logs will appear here once your project is deployed.''"},{"screen":"api_keys","trigger":"No API keys created","ui":"Key icon. Message: ''No API keys yet''. CTA: ''Generate API key''. Warning: ''Keep your keys secure. Never share them publicly.''."}],"loading_states":[{"screen":"dashboard","ui":"Metrics skeleton — grey rectangles same size as real values. Build list skeleton rows — status icon placeholder, project name, timestamp."},{"screen":"logs","ui":"Log lines appear as they stream — never batch. First 50 lines from cache immediately. New lines append at bottom with auto-scroll."},{"screen":"build_detail","ui":"Build steps list skeleton. Active step shows spinner. Completed steps show green check immediately — never wait for all steps."}],"error_flows":[{"trigger":"Build fails","ui":"Build status: red X. Error summary at top of build log. Failing step highlighted. Full error output below. CTA: ''View logs''. Never just ''Build failed'' with no detail."},{"trigger":"Deployment fails","ui":"Deployment status: red. Last successful deployment still live — shown clearly. Error detail expandable. Rollback CTA prominent."},{"trigger":"API key revoked or expired","ui":"API calls return 401. Dashboard shows alert: ''Your API key has been revoked''. Instructions to generate new key. Old key not shown."},{"trigger":"Rate limit hit","ui":"429 response shown in request log with reset time. Dashboard shows rate limit gauge. Warning before hitting limit at 80%."}],"edge_cases":[{"case":"Build log with 100k+ lines","ui":"Virtualised list — only render visible lines. Search within logs. Jump to error shortcut. Download full log option."},{"case":"Simultaneous deploys to multiple environments","ui":"Each environment shown as separate row with own status. Never collapse into single status when environments differ."},{"case":"API key used from unexpected location","ui":"Security alert in dashboard: ''Unusual API key usage detected from [country]''. Option to revoke immediately. Never silent."},{"case":"Zero downtime deploy in progress","ui":"Two rows shown — old version winding down, new version spinning up. Traffic split shown as progress bar. Both statuses visible simultaneously."}]},"components":["BuildStatusBadge","LogLine","ProjectRow","APIKeyCard","CodeBlock","DeployButton","EnvVarRow","UsageChart"],"nav_active_states":{"dashboard":"Dashboard","project_detail":"Projects","build_detail":"Projects","logs":"Projects","api_keys":"Dashboard","documentation":"Dashboard","usage":"Dashboard","settings":"Settings"}}'