  ('finance_banking', 'Finance Banking', 'Personal finance and banking app — accounts, transactions, cards, budgets, savings goals. Finance industry only.', ARRAY['Finance'], '{"archetype_id":"finance_banking","archetype_name":"Finance Banking","description":"Personal finance and banking app — accounts, transactions, cards, budgets, savings goals. Finance industry only.","valid_industries":["Finance"],"routing_note":"Finance × Dashboard SaaS routes here instead of dashboard_core. Finance is the only industry where Dashboard SaaS means a banking/fintech product, not a generic B2B SaaS.","icon_pack":{"default_library":{"name":"Material Symbols","variant":"Outlined","url":"https://fonts.google.com/icons"},"industry_overrides":{"Finance":{"name":"Material Symbols","variant":"Sharp","url":"https://fonts.google.com/icons"},"Healthcare":{"name":"Material Symbols","variant":"Rounded","url":"https://fonts.google.com/icons"},"Transport & Logistics":{"name":"Material Symbols","variant":"Sharp","url":"https://fonts.google.com/icons"},"Developer Tools":{"name":"Material Symbols","variant":"Sharp","url":"https://fonts.google.com/icons"}},"core_nav_icons":["home","bar_chart","group","description","person","notifications","settings","arrow_back","menu","refresh"],"core_domain_icons":["bar_chart","trending_up","pie_chart","table_chart","filter_list","download","upload","search","tune","more_vert"]},"landing_page":{"sections":[{"id":"hero","generates_images":false},{"id":"stats_bar","generates_images":false},{"id":"pricing","generates_images":false},{"id":"cta_footer","generates_images":false}],"three_js":{"style":"geometric_grid","description":"Precise orthographic grid lines with floating number clusters. Clean and architectural. No organic shapes. Gold accent lines pulse at intersections.","intensity":"very_subtle","interaction":"mouse_parallax","avoid":"no status pills, no hero-stat-line, no ticker strips"}},"core_entities":{"entities":["User","Account","Transaction","Budget","Go