nsaction","Metric"],"actions":["Select report type","Set date range","View chart","View data table","Export PDF or CSV"]},{"id":"spending_report","name":"Spending Report","purpose":"Detailed spending with peer comparison and trend","visual":"Donut chart. Month selector. Category list. Trend line vs previous periods.","entities":["Transaction","Report","Metric"],"actions":["All MVP actions","Compare to previous periods","View trend line"]},{"id":"net_worth","name":"Net Worth","purpose":"Net worth history, assets vs liabilities breakdown","visual":"Net worth trend line over 12 months. Assets vs liabilities stacked bar. Account breakdown.","entities":["Account","Metric"],"actions":["View net worth history","View assets breakdown","View liabilities breakdown","Change time range"]},{"id":"alerts","name":"Alerts & Notifications","purpose":"Smart alerts with custom thresholds and rule management","visual":"Active alerts. Alert rules list. Create rule form. Severity badges.","entities":["Alert","Transaction","Budget"],"actions":["All MVP actions","Create custom alert rule","Set threshold value","Set delivery channel","View rule history"]},{"id":"connect_account","name":"Connect Account","purpose":"Full account connection with manual and open banking","visual":"Institution search. OAuth flow. Manual entry. Investment account support. Crypto wallet.","entities":["Account","Integration"],"actions":["All MVP actions","Connect investment account","Connect crypto wallet","Manual investment entry"]},{"id":"sharing","name":"Sharing & Collaboration","purpose":"Share financial view with accountant, advisor, or partner","visual":"Shared access list. Role per user — viewer, editor. Invite by email.","entities":["User","Organisation"],"actions":["Invite viewer or editor","Set access level","Remove access","View what shared user can see"]},{"id":"settings","name":"Settings","purpose":"Full settings with currency, fiscal year, and security","visual":"Settings list. Base currency. Fiscal year. Two-factor. Privacy. Data export.","entities":["User"],"actions":["All MVP actions","Set base currency","Set fiscal year start","Manage shared access","Tax settings"]}],"interaction_patterns":["All MVP interaction patterns","Net worth trend line — hover to see exact value at any point in time","Goal progress — milestone dots on progress bar — celebrate on milestone hit","Portfolio allocation donut — tap segment to highlight and show percentage","Cash flow bar — income bars above zero line, expense bars below","Bill due soon — amber highlight when due within 7 days, red when overdue","Receipt attachment — camera icon on transaction detail — photo uploads inline","Rollover budget — carry-over amount shown in muted text at budget top"]},"scale":{"tier":"Scale","description":"Enterprise finance platform — multi-entity, approval workflows, compliance, treasury management, and audit.","screen_count":24,"primary_flows":["All MVP and Startup flows","Multi-entity org — manage finances for multiple companies under one platform","Expense approval workflow — employee submits → manager approves → finance processes → accounting synced","Compliance officer runs audit → exports full transaction log → satisfies regulatory requirement","Treasury manager views cash positions across entities → forecasts liquidity → takes action","Finance admin connects ERP → transactions sync bidirectionally → reconciliation automated"],"secondary_flows":["All previous secondary flows","Purchase order management","Vendor payment management","Intercompany transactions","Custom chart of accounts","Automated bank reconciliation"],"screens":[{"id":"dashboard","name":"Financial Dashboard","purpose":"Executive financial overview with entity switcher and treasury summary","visual":"Entity switcher. Consolidated KPIs. Treasury position. Cash forecast. Recent actions.","entities":["Account","Transaction","Metric","Budget","Goal"],"actions":["All Startup actions","Switch entity","View consolidated view","View treasury position"]},{"id":"entities","name":"Multi-Entity Management","purpose":"Manage multiple legal entities under one platform","visual":"Entity cards. Financial summary per entity. Intercompany toggle. Consolidate view.","entities":["Organisation"],"actions":["View all entities","Switch entity context","View consolidated financials","Manage intercompany transactions","Add entity"]},{"id":"accounts","name":"Accounts","purpose":"Multi-entity accounts with ERP sync status","visual":"Account list. ERP sync badge. Reconciliation status. Balance.","entities":["Account","Integration"],"actions":["All Startup actions","View ERP sync status","View reconciliation status","Trigger manual sync"]},{"id":"transactions","name":"Transactions","purpose":"Full transactions with approval status and ERP reference","visual":"Transaction list. Approval status badge. ERP reference. Reconciled indicator.","entities":["Transaction","Account"],"actions":["All Startup actions","Filter by approval status","View ERP reference","View reconciliation status"],"copy":{"headline":"Transactions","cta":"Add account","empty_state":"No transactions yet. Connect a bank account to get started."}},{"id":"transaction_detail","name":"Transaction Detail","purpose":"Full detail with approval history, ERP link, and audit trail","visual":"Amount. Details. Approval chain. ERP link. Audit trail.","entities":["Transaction","Account"],"actions":["All Startup actions","View approval history","View ERP record","View full audit trail"]},{"id":"expenses","name":"Expense Management","purpose":"Employee expense submission, approval, and reimbursement","visual":"Expense list. Status — submitted, approved, rejected, paid. Submit CTA. Bulk approve.","entities":["Transaction","User"],"actions":["Submit expense","Attach receipt","View expense status","Approve or reject","Bulk approve","Process reimbursement"]},{"id":"expense_detail","name":"Expense Detail","purpose":"Expense review — receipt, policy check, approval action","visual":"Receipt image. Amount. Category. Policy compliance badge. Approve or reject.","entities":["Transaction","User"],"actions":["View receipt","Check policy compliance","Approve expense","Reject with reason","Request more info"]},{"id":"approvals","name":"Approval Workflows","purpose":"Configure and manage multi-level approval workflows","visual":"Workflow list. Step builder. Threshold rules. Approver assignment.","entities":["Transaction","User"],"actions":["Create workflow","Set approval thresholds","Assign approvers per level","Set auto-approve rules","View workflow activity"]},{"id":"budgets","name":"Budgets","purpose":"Department and project budgets with approval and forecast","visual":"Budget table. Department breakdown. Approval status. Forecast vs actual.","entities":["Budget","Transaction"],"actions":["All Startup actions","Create department budget","Submit budget for approval","View forecast vs actual","View over-budget alerts"]},{"id":"cash_flow","name":"Cash Flow & Treasury","purpose":"Treasury cash position across entities with scenario planning","visual":"Cash position per entity. Consolidated view. Scenario modelling. Forecast.","entities":["Transaction","Account","Metric"],"actions":["All Startup actions","View cash position per entity","Run scenario model","View 90 day forecast","Set liquidity alerts"]},{"id":"reconciliation","name":"Bank Reconciliation","purpose":"Automated and manual bank reconciliation","visual":"Reconciliation table. Matched pairs. Unmatched items. Reconcile CTA.","entities":["Transaction","Account"],"actions":["View matched transactions","View unmatched items","Manually match","Create adjustment","Complete reconciliation","Export reconciliation report"]},{"id":"reports","name":"Reports","purpose":"Full financial reporting — P&L, balance sheet, cash flow statement","visual":"Report type selector. Period selector. P&L view. Balance sheet view. Export.","entities":["Report","Transaction","Metric"],"actions":["View P&L","View balance sheet","View cash flow statement","Compare periods","Export for audit","Schedule report delivery"]},{"id":"vendor_payments","name":"Vendor Payments","purpose":"Manage and process vendor payments with approval","visual":"Vendor list. Outstanding invoices. Schedule payment. Approval status. Payment history.","entities":["Transaction","Organisation"],"actions":["View vendor invoices","Schedule payment","Approve payment","View payment history","Batch payments"]},{"id":"integrations","name":"Integrations","purpose":"ERP, accounting, payroll, and banking integrations","visual":"Integration cards. ERP section prominent. Sync status. Last sync time.","entities":["Integration","Organisation"],"actions":["Connect ERP","Connect accounting software","Connect payroll","Configure sync rules","View sync log","Manual sync"]},{"id":"audit_log","name":"Audit Log","purpose":"Full immutable audit trail of all financial actions","visual":"Audit table. User, action, amount, timestamp. Immutable indicator. Export.","entities":["AuditLog","User","Transaction"],"actions":["View full audit log","Filter by user or action","Filter by date range","Export for regulator","View immutability proof"]},{"id":"compliance","name":"Compliance Centre","purpose":"Regulatory compliance — KYC, AML, reporting obligations","visual":"Compliance status cards. KYC queue. AML alert queue. Regulatory report list.","entities":["Transaction","User","Organisation"],"actions":["View compliance status","Process KYC checks","Review AML alerts","Generate regulatory report","View compliance history"]},{"id":"team_management","name":"Team Management","purpose":"Finance team with roles — CFO, controller, accountant, viewer","visual":["Team table. Finance roles. Permissions per role. Department assignment."],"entities":["User","Team","Role"],"actions":["Invite team member","Assign finance role","Set department access","View team activity","Manage external access — accountant, auditor"]},{"id":"alert_rules","name":"Alerts & Rules","purpose":"Advanced alert rules — fraud, compliance, cash thresholds","visual":"Rule list. Rule type — fraud, budget, cash, compliance. Severity. Action.","entities":["Alert","Transaction","Account"],"actions":["Create alert rule","Set rule conditions","Set severity","Set action — notify, block, escalate","View rule trigger history"]},{"id":"custom_fields","name":"Custom Fields & Chart of Accounts","purpose":"Custom transaction fields and chart of accounts management","visual":"COA tree structure. Custom field list. Create field. Map to COA.","entities":["Transaction","Organisation"],"actions":["View chart of accounts","Add account code","Create custom transaction field","Map field to COA","Import COA"]},{"id":"net_worth","name":"Financial Position","purpose":"Consolidated financial position across all entities","visual":"Consolidated assets vs liabilities. Per-entity breakdown. Trend. Export.","entities":["Account","Metric"],"actions":["All Startup actions","View per-entity breakdown","View consolidated","Export position report"]},{"id":"subscription","name":"Subscription & Plan","purpose":"Enterprise plan, seats, and billing management","visual":"Enterprise plan card. Seat usage. Feature limits. Billing contact. Invoices.","entities":["Subscription","Organisation"],"actions":["View plan details","Manage seats","Update billing contact","Download invoices","Contact enterprise sales"]},{"id":"sso_security","name":"SSO & Security","purpose":"Enterprise SSO, MFA enforcement, and session policy","visual":"SSO config. MFA toggle. Session policy. IP restrictions. Active sessions.","entities":["User"],"actions":["Configure SSO","Enforce MFA","Set session timeout","IP allowlist","View active sessions"]},{"id":"settings","name":"Settings","purpose":"Enterprise settings — entities, compliance, integrations, security","visual":"Settings sidebar. Entity management. Compliance. Integrations. SSO. Audit.","entities":["User","Organisation","Subscription"],"actions":["All Startup actions","Entity settings","Compliance settings","ERP integration settings","Audit log settings"]},{"id":"help_centre","name":"Help Centre","purpose":"Financial platform help with compliance and integration guidance","visual":"Search. Categories — getting started, compliance, integrations, reporting. Contact.","entities":["User"],"actions":["Search articles","Browse compliance guides","Browse integration docs","Contact enterprise support"]}],"interaction_patterns":["All MVP and Startup interaction patterns","Entity switcher — dropdown at top of nav — switches all data context","Approval chain visual — step bubbles — completed green, pending amber, rejected red","Expense policy badge — compliant green, violation red — appears on expense card","Reconciliation matched pair — connecting line between matched rows","Audit log rows — immutable lock icon — cannot be deleted or edited","P&L toggle — actuals vs budget vs forecast — tabs on report","Cash flow scenario model — adjust assumption sliders — chart updates live","Bulk approve — checkbox select expenses — single approve action"]}},"layout":{"iphone":{"nav":"bottom_tab_5","nav_items":["Home","Accounts","Transactions","Cards","Profile"],"content":"full_width_single_column_financial_cards","card_style":"balance_card_full_width_with_gradient","cta":"quick_action_row_below_balance_card","hero":"balance_card_top_then_recent_transactions","padding":"16px horizontal","image_ratio":"no_photography_financial_cards_only"},"ipad":{"nav":"sidebar_left_with_labels","nav_items":["Home","Accounts","Transactions","Cards","Budgets","Profile"],"content":"2col_accounts_left_transactions_right","card_style":"account_card_with_mini_chart","cta":"send_money_prominent_top_right","hero":"accounts_overview_left_recent_activity_right","padding":"24px","image_ratio":"no_photography"},"desktop":{"nav":"sidebar_left_fixed_with_section_groups","nav_items":["Overview","Accounts","Transactions","Cards","Budgets","Analytics","Settings"],"content":"left_anchored_max_1200px_with_sidebar","card_style":"account_rows_with_balance_and_sparkline","cta":"top_right_transfer_button","hero":"portfolio_overview_full_width_then_account_rows","padding":"32px content","image_ratio":"no_photography_charts_and_cards_only"},"notes":"Balance is always the hero — the most prominent number on every home screen across all form factors. Sensitive data masked by default — tap to reveal. Biometric confirmation before any money movement."},"constraints":{"avoid":["Never show full account number — mask all but last 4 digits always","Never use red for anything except genuinely negative balances, failed payments, or overdraft states","Never use green for anything except positive balances, completed transactions, and successful payments","Never animate balance numbers casually — counter animations only on first load, never on refresh","Never use playful fonts, rounded bubbly UI, or casual illustrations — trust requires precision","Never show a transaction without: date, merchant name, amount, and status","Never allow destructive actions without biometric or PIN confirmation","Never auto-log out without warning — always show session timeout countdown with extend option"],"enforce":["Balance always shown with 2 decimal places — £1,234.56 never £1,234","Debit transactions in red, credit transactions in green — always, no exceptions","Transaction amount always right-aligned in transaction lists","Biometric authentication offered on every app open after initial setup","Security lock icon visible in header on all sensitive screens","Transaction pending state always shown distinctly — pending label, grey amount","Card number masked by default — tap eye icon to reveal temporarily","Send money confirmation always shows: recipient name, amount, fee if any — before final confirm"]},"states":{"empty_states":[{"screen":"dashboard","trigger":"New account, zero balance","ui":"Card visual shown with £0.00. ''Add money to get started'' CTA prominent. Quick action buttons visible but greyed if insufficient balance — never hidden."},{"screen":"transactions","trigger":"No transactions yet","ui":"Transaction list illustration. Message: ''No transactions yet''. Sub: ''Your transactions will appear here''. CTA: ''Add money''."},{"screen":"cards","trigger":"No physical card ordered","ui":"Card placeholder illustration. Message: ''Order your card''. CTA: ''Get a card''. Show estimated delivery time."}],"loading_states":[{"screen":"dashboard","ui":"Balance skeleton — large number placeholder shimmer. Card visual loads immediately from cache. Transaction list skeleton — 5 rows with amount placeholder right-aligned."},{"screen":"transactions","ui":"Date group headers load first. Transaction rows skeleton — merchant name left, amount right, both shimmer. Never reorder transactions during load."},{"screen":"send_money","ui":"Recipient lookup shows spinner in search field. Amount field active immediately. Fee calculation shows ''Calculating...'' then updates."}],"error_flows":[{"trigger":"Insufficient funds","ui":"Payment blocked. Red inline error: ''Insufficient funds. Your balance is [amount]''. Show shortfall. CTA: ''Top up'' or ''Pay less''. Never just decline silently."},{"trigger":"Card declined","ui":"Full screen error: ''Payment declined''. Reason if available: ''Insufficient funds / Card blocked / Incorrect PIN''. Contact support CTA. Never cryptic code."},{"trigger":"Bank transfer fails","ui":"Transaction shows failed state in history. Money returned to balance immediately. Notification sent. Retry with corrected details option."},{"trigger":"Suspicious transaction detected","ui":"Push notification immediately. In-app: ''We noticed unusual activity''. Transaction temporarily frozen. Options: ''This was me'' / ''This wasn''t me''. Instant card freeze if needed."}],"edge_cases":[{"case":"Negative balance (overdraft)","ui":"Balance shown in red. Overdraft limit and usage shown clearly. Warning banner. No new outgoing transactions allowed unless overdraft is authorised."},{"case":"Large transaction (above threshold)","ui":"Additional verification step — biometric plus reason for payment. This is a trust and compliance requirement, not optional."},{"case":"International transaction with FX fee","ui":"Show original currency amount, exchange rate, and fee all before confirmation. Never hide the FX cost until after payment."},{"case":"Simultaneous transactions reducing balance","ui":"Available balance updates in real time. Pending transactions shown with clock icon. Available balance = total minus pending."}]},"components":["BalanceCard","TransactionRow","CardWidget","SpendingChart","QuickActionButton","AmountInput","AccountSelector"],"nav_active_states":{"home":"Home","accounts":"Accounts","transactions":"Transactions","transaction_detail":"Transactions","budgets":"Home","spending_report":"Home","connect_account":"Accounts","alerts":"Home","settings":"Profile"}}'::jsonb, 11),
  ('lms_course_builder', 'LMS / Course Builder', 'Instructor-side tool — create courses, manage students, assignments, grades, and learning outcomes. Education industry only.', ARRAY['Education'], '{"archetype_id":"lms_course_builder","archetype_name":"LMS / Course Builder","description":"Instructor-side tool — create courses, manage students, assignments, grades, and learning outcomes. Education industry only.","valid_industries":["Education"],"icon_pack":{"default_library":{"name":"Phosphor Icons","variant":"Rounded","url":"https://phosphoricons.com"},"industry_overrides":{},"core_nav_icons":["house","book","users","assignment","chart-bar","calendar","bell","arrow-left","magnifying-glass","gear"],"core_domain_icons":["book","graduation-cap","pencil","certificate","users","assignment","chart-bar","clock","trophy","lightbulb"]},"landing_page":{"sections":[{"id":"hero","generates_images":false},{"id":"how_it_works","generates_images":false},{"id":"pricing","generates_images":false},{"id":"cta_footer","generates_images":false}],"three_js":{"style":"knowledge_graph","description":"Interconnected node graph where nodes represent topics and edges represent learning paths. Nodes light up sequentially suggesting progression.","intensity":"subtle","interaction":"mouse_parallax","avoid":"no status pills, no hero-stat-line, no ticker strips"}},"core_entities":{"entities":["Instructor","Student","Course","Module","Lesson","Assignment","Submission","Grade","Enrollment","Certificate","Discussion","Announcement"],"relationships":["Instructor creates many Courses","Course has many Modules in order","Module has many Lessons","Course has many Assignments","Student enrolls in Course via Enrollment","Student submits Assignment via Submission","Submission receives a Grade from Instructor","Certificate belongs to Student for a completed Course","Discussion belongs to Course or Lesson","Announcement belongs to Course, sent to all enrolled Students"]},"tiers":{"mvp":{"tier":"MVP","descrip