st submission''. Grade recorded but flagged as self-graded. Not counted in student averages."}]},"components":["CourseCard","StudentRow","AssignmentCard","GradeInput","ProgressRing","AnnouncementBanner","DiscussionThread","CertificateBadge"],"nav_active_states":{"instructor_home":"Dashboard","courses":"Courses","course_builder":"Courses","lesson_editor":"Courses","students":"Students","student_detail":"Students","assignments":"Courses","grading":"Courses","gradebook":"Students","profile_settings":"Profile"}}'::jsonb, 12),
