Appointments","Prescriptions","Records","Profile"],"content":"full_width_single_column_health_cards","card_style":"full_width_appointment_and_metric_cards","cta":"book_appointment_sticky_bottom_on_home","hero":"upcoming_appointment_card_top_then_health_metrics","padding":"16px horizontal","image_ratio":"1:1 doctor avatar no_full_bleed_photography"},"ipad":{"nav":"sidebar_left_with_labels","nav_items":["Home","Appointments","Prescriptions","Records","Messages","Profile"],"content":"2col_health_summary_left_detail_right","card_style":"health_summary_card_with_trend_chart","cta":"book_appointment_prominent_in_sidebar","hero":"health_dashboard_2col_metrics_and_appointments","padding":"24px","image_ratio":"1:1 doctor avatar"},"desktop":{"nav":"sidebar_left_fixed","nav_items":["Dashboard","Appointments","Prescriptions","Records","Messages","Settings"],"content":"left_anchored_max_1100px_with_sidebar","card_style":"health_metric_cards_3col_then_detail_list","cta":"book_appointment_top_right","hero":"health_kpi_row_then_upcoming_appointments_table","padding":"32px content","image_ratio":"1:1 doctor avatar no_photography"},"notes":"Light background always — clinical trust. Never dark mode by default. Accessibility first — minimum 16px body, high contrast on all medical information."},"constraints":{"avoid":["Never use dark mode as the default — healthcare requires high contrast light UI for readability","Never use red for branding or decorative elements — red means urgency or danger in this context","Never truncate medical information — always show full prescription name, dosage, and instructions","Never use informal language in medical contexts — always precise and clinical","Never show another patient''s data — role separation is absolute","Never allow appointment booking without confirming insurance coverage where applicable","Never hide cancellation policy — always shown before booking confirmed","Never use gamification elements (streaks, badges, points) for medication adherence — trivialises compliance"],"enforce":["Medication instructions always shown in full — never truncated","Doctor credentials always verified badge visible","Appointment status always colour-coded: confirmed green, pending amber, cancelled grey","Emergency contact and crisis resources always one tap away from profile","All health data changes logged with timestamp — audit trail","HIPAA compliance badge visible on any messaging or data sharing screen","Prescription expiry date always shown — amber warning 7 days before expiry","Lab results always shown with reference range — never just the value"]},"states":{"empty_states":[{"screen":"home","trigger":"New patient, no history","ui":"Welcome card with profile completion prompt. ''Complete your health profile'' progress bar. Upcoming appointments section shows ''Book your first appointment'' CTA."},{"screen":"medical_records","trigger":"No records yet","ui":"Document illustration. Message: ''Your medical records will appear here''. Sub: ''Records are added after your appointments''. No empty table."},{"screen":"prescriptions","trigger":"No active prescriptions","ui":"Pill bottle illustration. Message: ''No active prescriptions''. Sub: ''Prescriptions from your doctor will appear here''. Never show empty rows."}],"loading_states":[{"screen":"home","ui":"Health summary card skeleton. Upcoming appointment card skeleton. Active prescription skeleton pills row. All shimmer simultaneously."},{"screen":"medical_records","ui":"Record list skeleton — date left, title centre, type badge right. 5 rows shimmer. Category tabs visible and interactive during load."},{"screen":"book_appointment","ui":"Calendar loads from cache immediately. Doctor availability skeleton chips in time slot grid. Show ''Loading availability...'' below calendar."}],"error_flows":[{"trigger":"Appointment slot no longer available","ui":"Full screen: ''That slot was just booked''. Next available slots shown immediately — no extra tap. Pre-selected doctor retained."},{"trigger":"Prescription sync fails","ui":"Prescription list shows last known state with ''Last updated [time]'' label. Warning badge. Retry button. Never show stale data as current without warning."},{"trigger":"Lab results delayed","ui":"Lab result card shows ''Results pending''. Estimated ready date shown. Push notification promised: ''We''ll notify you when results are ready''."},{"trigger":"Telehealth connection fails","ui":"Waiting room screen: ''Connection issue''. Auto-retry 3 times with countdown. If still failing: ''Switching to phone call'' option offered. Appointment not marked as missed."}],"edge_cases":[{"case":"Medication interaction detected","ui":"Red warning banner on prescription detail: ''Potential interaction with [medication]''. Full interaction details. ''Contact your doctor'' CTA prominent. Never hide this information."},{"case":"Minor patient (under 18)","ui":"Parent/guardian access controls visible. Sensitive information (mental health, reproductive health) requires explicit minor consent or is hidden from guardian view per regional law."},{"case":"Out of network doctor selected","ui":"Warning before booking confirmation: ''This provider is out of network. Estimated cost: [amount]''. In-network alternatives shown. User must acknowledge before proceeding."},{"case":"Critical lab value (severely abnormal)","ui":"Push notification immediately. In-app: red urgent banner on result. Message: ''Please contact your doctor immediately''. Emergency contact shown. Never just show the value without context."}]},"components":["AppointmentCard","PrescriptionRow","HealthMetricCard","DoctorCard","MedicationReminder","LabResultRow"],"nav_active_states":{"home":"Home","appointments":"Appointments","book_appointment":"Appointments","prescriptions":"Prescriptions","medical_records":"Records","health_metrics":"Home","doctor_profile":"Appointments","messages":"Messages","profile_settings":"Profile"}}'::jsonb, 13),
