s":["Unit","RentPayment"],"actions":["View occupancy calendar","Manage channel distribution","Set dynamic pricing rules","View revenue analytics"]},{"id":"hoa_management","name":"HOA Management","purpose":"HOA dues, violations, and community management","visual":"HOA dues tracker. Violation queue. Meeting minutes. Reserve fund.","entities":["Property","Tenant"],"actions":["Track HOA dues","Log violation","Send violation notice","Manage reserve fund","Schedule meeting"]},{"id":"leases","name":"Leases","purpose":"Enterprise lease management with escalations and options","visual":"Lease list. Escalation schedule. Option dates. Renewal pipeline.","entities":["Lease","Tenant","Unit"],"actions":["All Startup actions","View rent escalation schedule","Track lease options","View renewal pipeline"]},{"id":"maintenance","name":"Maintenance","purpose":"Portfolio-wide maintenance with budget tracking","visual":"All requests. Property filter. Budget vs actual maintenance spend. Contractor performance.","entities":["MaintenanceRequest","Unit","Tenant"],"actions":["All Startup actions","View maintenance budget","Contractor performance stats","Recurring maintenance schedule"],"copy":{"headline":"Maintenance requests","cta":"Log request","empty_state":"No open requests. All clear."}},{"id":"financials","name":"Financials","purpose":"Full portfolio P&L with owner distributions","visual":"Portfolio P&L. Per property breakdown. Distribution calculator. Export.","entities":["RentPayment","Expense","Property"],"actions":["All Startup actions","Calculate owner distributions","View per property P&L","Consolidated P&L","Export for audit"]},{"id":"team_management","name":"Team Management","purpose":"Property managers, assistants, and roles","visual":"Team list. Role badge. Property assignments. Activity log.","entities":["Landlord"],"actions":["Add team member","Assign properties","Set permissions","View activity log","Remove member"]},{"id":"documents","name":"Documents","purpose":"Enterprise document management with compliance tracking","visual":"Document library. Compliance status. Expiry calendar. Bulk upload.","entities":["Document","Property","Lease"],"actions":["All Startup actions","Compliance status view","Expiry calendar","Bulk upload","Version control"]},{"id":"reports","name":"Reports","purpose":"Full reporting suite — owner, tax, regulatory","visual":"Report library. Owner reports. Tax reports. Regulatory filings.","entities":["RentPayment","Expense","Property"],"actions":["All Startup actions","Owner report","Tax schedule E","Regulatory reports","Custom report builder"]},{"id":"admin_dashboard","name":"Admin — Platform","purpose":"Platform admin — all portfolios, billing, support","visual":"Portfolio table. Revenue. Support queue. Usage stats.","entities":["Landlord","Property"],"actions":["View all portfolios","View platform revenue","Support queue","Usage analytics"]},{"id":"profile_settings","name":"Profile & Settings","purpose":"Enterprise settings — accounting, owners, compliance","visual":"Comprehensive settings. Accounting integration. Owner management. Compliance.","entities":["Landlord"],"actions":["All Startup actions","Accounting settings","Owner portal settings","Compliance settings"]}],"interaction_patterns":["All MVP and Startup patterns","Owner distribution calculator — inputs NOI and expenses, outputs distribution amount","CAM reconciliation — annual process, step-by-step with approval","Portfolio heat map — properties coloured by performance metric","Accounting sync status — live indicator, error badge if sync fails","Compliance expiry calendar — red on expired, amber 30 days out"]}},"layout":{"iphone":{"nav":"bottom_tab_5","nav_items":["Dashboard","Properties","Tenants","Maintenance","Financials"],"content":"full_width_kpi_cards_then_list","card_style":"full_width_property_status_card","cta":"floating_action_button_bottom_right","hero":"kpi_cards_stacked_then_alert_list","padding":"16px horizontal","image_ratio":"16:9 property thumbnail no_full_bleed"},"ipad":{"nav":"sidebar_left_with_labels","nav_items":["Dashboard","Properties","Tenants","Maintenance","Financials","Documents"],"content":"2col_list_left_detail_right","card_style":"property_row_with_status_badges","cta":"top_right_add_property_button","hero":"kpi_row_3col_then_property_list","padding":"24px","image_ratio":"4:3 property photo in list"},"desktop":{"nav":"sidebar_left_fixed_with_section_groups","nav_items":["Dashboard","Properties","Units","Tenants","Rent","Maintenance","Financials","Documents","Reports"],"content":"left_anchored_max_1440px_with_sidebar","card_style":"data_table_rows_with_status_colour_coding","cta":"top_right_header_primary_action","hero":"4col_kpi_row_then_property_table","padding":"32px content","image_ratio":"4:3 property thumbnail in table"},"notes":"Rent status colour coding must be consistent across all form factors — green paid, amber due, red overdue. This is the single most important data signal in the product."},"constraints":{"avoid":["Never show financial data without specifying currency","Never mix income and expense in the same row without clear visual separation","Never send automated communications to tenants without landlord preview and confirmation","Never delete a record permanently — always archive with full history preserved","Never auto-apply late fees without explicit rule configuration and landlord confirmation","Never show occupancy rate as a percentage without the underlying unit count","Never use a modal for maintenance request details — full screen navigation","Never collapse property financial history — always show full audit trail"],"enforce":["Rent status always colour-coded: paid green, due amber, overdue red — across every screen","Maintenance priority always shown: urgent red, normal amber, low grey","Lease expiry always shown with days remaining — red under 30 days, amber under 90","All financial figures right-aligned in lists and tables","Tenant communication history always preserved and viewable","Late fee calculations always shown with breakdown — never just a total","Inspection reports always include date, inspector, and photo evidence count","All bulk actions require confirmation showing exactly how many records are affected"]},"states":{"empty_states":[{"screen":"dashboard","trigger":"No properties added yet","ui":"Building illustration. Message: ''Add your first property to get started''. CTA: ''Add property''. Step-by-step onboarding checklist: add property, add units, add tenants."},{"screen":"maintenance","trigger":"No maintenance requests","ui":"Wrench illustration. Message: ''No maintenance requests''. Sub: ''Requests submitted by tenants will appear here''. Not ''nothing to do'' — this is expected positive state."},{"screen":"financials","trigger":"No transactions recorded yet","ui":"Chart illustration. Message: ''Financial data will appear here''. Sub: ''Record your first rent payment or expense to see reports''."}],"loading_states":[{"screen":"dashboard","ui":"KPI cards skeleton — 4 cards in row shimmer. Property list skeleton below — 3 property rows with status badge placeholder."},{"screen":"rent_tracking","ui":"Tenant rows skeleton — name left, due date centre, amount right, status badge far right. All shimmer. Month selector visible and interactive."},{"screen":"maintenance","ui":"Request cards skeleton — title, property badge, status badge, date. 4 skeleton cards shimmer."}],"error_flows":[{"trigger":"Rent payment recording fails","ui":"Form stays open. Red inline error at top. Specific reason shown. Payment NOT recorded. Retry with same details — no re-entry needed."},{"trigger":"Tenant communication fails to send","ui":"Message draft preserved. Red error: ''Message not sent''. Retry option. Option to copy and send manually. Never silently drop the message."},{"trigger":"Lease document generation fails","ui":"Error shown with reason. Draft data preserved. Option to try again or download editable template instead."},{"trigger":"Maintenance contractor notification fails","ui":"Toast: ''Could not notify contractor''. Request still saved. Option to notify manually — phone or email shown. Status not automatically updated to assigned."}],"edge_cases":[{"case":"Property with 0% occupancy","ui":"Vacancy alert shown prominently on property card. Red occupancy badge. ''List vacant unit'' CTA shown directly on dashboard card."},{"case":"Lease ending in the past (overdue renewal)","ui":"Lease shown as ''Expired'' in red. Urgent banner on tenant detail: ''Lease expired [X days] ago. Renew or begin eviction process.'' Legal resources linked."},{"case":"Multiple tenants on same unit (joint tenancy)","ui":"All tenant names shown on unit. Rent split configuration shown. Communications sent to all tenants by default. One tenant paying full rent is a separate config."},{"case":"Maintenance request from unknown tenant","ui":"Request flagged as ''Unknown submitter''. Landlord notified. Option to link to existing tenant, add new tenant, or reject request."}]},"components":["PropertyCard","TenantRow","RentStatusBadge","MaintenanceCard","LeaseChip","FinancialSummary","InspectionRow"],"nav_active_states":{"dashboard":"Dashboard","properties":"Properties","property_detail":"Properties","tenants":"Tenants","tenant_detail":"Tenants","rent_tracking":"Financials","maintenance":"Maintenance","financials":"Financials","profile_settings":"Settings"}}'::jsonb, 14),
  ('trip_planner', 'Trip Planner', 'Itinerary builder, day-by-day trip planning, packing lists, travel documents, and group travel coordination. Travel & Lifestyle industry only.', ARRAY['Travel & Lifestyle'], '{"archetype_id":"trip_planner","archetype_name":"Trip Planner","description":"Itinerary builder, day-by-day trip planning, packing lists, travel documents, and group travel coordination. Travel & Lifestyle industry only.","valid_industries":["Travel & Lifestyle"],"icon_pack":{"default_library":{"name":"Lucide","variant":"Rounded line","url":"https://lucide.dev"},"industry_overrides":{},"core_nav_icons":["home","map","plus-circle","heart","user","bell","calendar","list","arrow-left","search"],"core_domain_icons":["plane","map-pin","calendar","luggage","camera","compass","sun","clock","users","bookmark"]},"landing_page":{"sections":[{"id":"hero","generates_images":true},{"id":"how_it_works","generates_images":false},{"id":"cta_footer","generates_images":false}],"three_js":{"style":"starfield_globe","description":"Slow starfield depth effect with a faint wireframe globe in the background. Travel and exploration energy. Destination dots appear across the globe.","intensity":"subtle","interaction":"mouse_rotate","avoid":"no status pills, no hero-stat-line, no ticker strips"}},"core_entities":{"entities":["User","Trip","Day","Activity","Accommodation","Flight","PackingList","PackingItem","TravelDocument","TripMember","Note"],"relationships":["User creates many Trips","Trip has many Days","Day has many Activities and an Accommodation","Trip has Flights (outbound and return)","Trip has a PackingList with PackingItems","Trip has TravelDocuments — visas, insurance, confirmations","Trip has TripMembers — for group travel","Activity has a location, time, cost, and booking reference","Note belongs to a Trip or Day — free text observations"]},"tiers":{"mvp":{"tier":"MVP","description":"Core trip planner — create trip, plan days, add activities.","screen_count":8,"primary_f