p actions","Use AI caption suggestion","Create memory highlight","Share journal"]},{"id":"admin_corporate","name":"Corporate Admin","purpose":"Company travel spend management","visual":"Spend dashboard. Policy violations. Approval queue. Top destinations.","entities":["Trip","User"],"actions":["View spend dashboard","Review violations","Approve trips","Set policy rules"]},{"id":"profile_settings","name":"Profile & Settings","purpose":"Full settings with loyalty, corporate, and AI preferences","visual":"Profile. Loyalty programs. Corporate settings. AI preferences.","entities":["User"],"actions":["All Startup actions","Loyalty program settings","Corporate account settings","AI preference tuning"]}],"interaction_patterns":["All MVP and Startup patterns","Travel alert banner — appears at top of trip when disruption detected","AI suggestion card — dismissible, learns from dismissals","Policy compliance chip — green approved, amber review, red violation","Carbon offset — progress bar toward carbon neutral trip","Loyalty points — earned on bookings, shown in real time"]}},"layout":{"iphone":{"nav":"bottom_tab_4","nav_items":["My Trips","Discover","Map","Profile"],"content":"full_width_single_column_trip_cards","card_style":"trip_card_full_width_destination_photo","cta":"create_trip_floating_button_bottom_right","hero":"active_trip_card_top_with_countdown_then_upcoming","padding":"16px horizontal","image_ratio":"16:9 trip cover photo"},"ipad":{"nav":"sidebar_left_with_labels","nav_items":["My Trips","Trip Detail","Map","Discover","Profile"],"content":"2col_trip_list_left_itinerary_right","card_style":"day_card_with_activity_timeline","cta":"add_activity_prominent_in_day_view","hero":"trip_overview_with_day_tabs_and_map_toggle","padding":"24px","image_ratio":"16:9 trip cover 4:3 activity photo"},"desktop":{"nav":"sidebar_left_fixed","nav_items":["My Trips","Itinerary","Map View","Documents","Budget","Profile"],"content":"left_anchored_itinerary_max_900px_map_panel_right","c