yle":"exercise_table_with_set_history_inline","cta":"start_workout_top_right_primary","hero":"progress_charts_full_width_then_recent_workouts","padding":"32px content","image_ratio":"exercise_diagram_landscape"},"notes":"During active workout on iPhone — hide all navigation. Full screen, only exercise name, sets, timer, and finish button. No distractions. On iPad and desktop — active workout shows in main panel, exercise list remains accessible in sidebar."},"constraints":{"avoid":["Never use small tap targets during active workout — minimum 56px for all workout logging actions","Never require more than 2 taps to log a set during active workout","Never auto-advance to next exercise without user confirmation","Never use subtle colours for active workout UI — high contrast only","Never show social content during active workout — dedicated focused mode","Never lose workout data on app close or phone lock — always persist in-progress workout","Never fabricate personal records — only show PR badge when genuinely beaten","Never show calorie counts as the primary metric — they are secondary to performance"],"enforce":["Active workout mode: full screen, no distractions, workout controls only","Rest timer starts automatically after set logged — user can dismiss or extend","Previous performance shown above input fields for each exercise — instant reference","PR badge animates on screen when personal record beaten — celebratory moment","Workout always auto-saved every 30 seconds — never lose data","Exercise weight increment buttons — +2.5kg and -2.5kg — large tap targets","Set logged haptic feedback — subtle but immediate confirmation","Workout duration timer always visible during active session"]},"states":{"empty_states":[{"screen":"home","trigger":"New user, no workout history","ui":"Start workout prompt centred. Quick start options: ''Upper body / Lower body / Full body / Custom''. No empty stats — hide stats section until first workout completed."},{"screen":"workout_history","trigger":"No completed workouts","ui":"Calendar shows current month with no activity. Message: ''Complete your first workout to see your history''. CTA: ''Start workout''. Heat map hidden until data exists."},{"screen":"personal_records","trigger":"No PRs set yet","ui":"Trophy illustration. Message: ''Log your first workout to set your records''. Sub: ''Your personal bests will track here automatically''."}],"loading_states":[{"screen":"home","ui":"Streak badge loads from cache immediately. Recent workouts skeleton — 3 rows with exercise count and duration placeholder. Program progress skeleton if applicable."},{"screen":"exercise_library","ui":"Search field active immediately. Exercise list skeleton — 8 rows with name and muscle group badge placeholder. Filter chips visible."},{"screen":"progress_charts","ui":"Chart skeleton rectangle. Metric selector chips visible and active. Date range selector visible. Data loads into chart without full page reload."}],"error_flows":[{"trigger":"Workout fails to save","ui":"Warning toast: ''Workout save failed''. Auto-retry in background. Local copy preserved. ''Sync when connected'' indicator. Never lose the session data."},{"trigger":"Exercise not found in library","ui":"Search shows: ''No results for [query]''. CTA: ''Create custom exercise''. Suggested similar exercises shown below."},{"trigger":"Wearable sync fails","ui":"Heart rate shows last known value with ''Disconnected'' label. Manual heart rate entry offered. Workout continues — wearable data is supplementary not blocking."},{"trigger":"PR not saved (sync error)","ui":"Local PR marked with sync pending icon. ''Will sync when connected'' message. PR celebrated locally even before sync confirms."}],"edge_cases":[{"case":"User attempts to log 0 reps or 0 weight","ui":"Inline validation: ''0 reps cannot be logged''. Prompt to enter valid values. Never log empty sets."},{"case":"Workout longer than 3 hours","ui":"Gentle check-in at 3h mark: ''Still working out?'' wi